// Reuse the OI the user ALREADY computes in the index.html OI analyser (KV
// `oi_store`, per pair: max pain / call+put walls / gamma flip / HVL) instead of
// a second manual entry. Snapshot those computed levels into TODAY's session slot
// of `range_line_oi` (frozen + dated → the forward-test join needs dated OI). CME
// pairs come from the analyser; any pair the analyser doesn't cover can still be
// entered manually (those slots are preserved — only analyser pairs are refreshed).
async function _rlSnapshotOIFromStore() {
  try {
    const raw = await kv.get('oi_store').catch(() => null);
    if (!raw) return 0;
    const oiStore = JSON.parse(raw).data ?? JSON.parse(raw);
    if (!oiStore || typeof oiStore !== 'object') return 0;
    const day = _rlSessionDate(null);
    const storeRaw = await kv.get('range_line_oi').catch(() => null);
    const store = storeRaw ? (JSON.parse(storeRaw).data ?? JSON.parse(storeRaw)) : {};
    store[day] = store[day] || {};
    const live = {};                                              // bot-consumable: key → [{price,source}]
    const regimes = {};                                           // key → 'PIN'|'BREAKOUT' (gamma regime)
    let n = 0;
    for (const [pair, inst] of Object.entries(oiStore)) {
      const key = (() => { try { return resolveKey(pair); } catch { return null; } })()
                  || String(pair).toLowerCase().replace(/[/_]/g, '');
      const levels = oiStoreToLevels(inst);
      if (levels.length) {
        store[day][key] = levels;                                 // dated forward-test artifact ({price,type})
        live[key] = levels.map(l => ({ price: l.price, source: l.type, tier: l.tier ?? null }));   // bot reads `source` + `tier`
        // Gamma regime (Lesson 5): +GEX = dealers long gamma → dampen (PIN / fade);
        // −GEX = short gamma → amplify (BREAKOUT / follow). The fade/follow selector.
        const gex = inst.exposures?.gex ?? 0;
        if (gex > 0) regimes[key] = 'PIN'; else if (gex < 0) regimes[key] = 'BREAKOUT';
        n++;
      }
    }
    if (!n) return 0;
    const dates = Object.keys(store).sort();
    for (const d of dates.slice(0, Math.max(0, dates.length - 120))) delete store[d];
    await kv.put('range_line_oi', JSON.stringify({ data: store, timestamp: Date.now() }));
    // Ship the bot-consumable artifact (today's OI levels, source=type, pip-based
    // tolerance) — the live OI strengthen/override gate reads this, like it reads
    // range_line_confluence. Rebuilt each cycle from the morning's analyser paste.
    await kv.put('range_line_oi_live', JSON.stringify({ data: { strategy: 'range-line-oi', generatedAt: new Date().toISOString(), date: day, tolPips: 10, instruments: live, regimes }, timestamp: Date.now() }));
    console.log(`[range-line-oi] snapshot ${n} pair(s) from oi_store → ${day} (+ range_line_oi_live)`);
    return n;
  } catch (e) { console.error('[range-line-oi] oi_store snapshot failed:', e.message); return 0; }
}
setInterval(_rlSnapshotOIFromStore, 10 * 60_000);                 // keep today's snapshot current with the morning paste
setTimeout(_rlSnapshotOIFromStore, 40_000);

// On-demand: pull the analyser's OI into today's forward-test slot now.
app.post('/api/range-line-bot/oi/sync', async (_req, res) => {
  try { const n = await _rlSnapshotOIFromStore(); res.json({ ok: true, pairsSnapshotted: n, date: _rlSessionDate(null) }); }
  catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ── OI history archive (day-over-day dynamics) ───────────────────────────────
// CME serves NO OI history, so it must be self-collected (course research idea #3
// — "start capturing early", it can't be back-filled). Each day this archives a
// COMPACT summary of every pair's `oi_store` entry into `oi_history` keyed by
// pair→date, so `oiDeltas` can compute what moved (walls firming/fading, max-pain
// shift, positioning building/unwinding) for the brief + card. The live raw paste
// (rawOI/rawChg) stays in `oi_store`; history keeps the derived summary (small).
function _oiHistorySummary(inst) {
  if (!inst || typeof inst !== 'object') return null;
  const topN = (arr) => (Array.isArray(arr) ? arr.slice(0, 8).map(w => ({ strike: w.strike, oi: w.oi, chg: w.chg ?? null, tier: w.tier ?? null })) : []);
  return {
    spot: inst.spot ?? null, maxPain: inst.maxPain ?? null,
    callWall: inst.callWall ?? null, putWall: inst.putWall ?? null,
    callWallOI: inst.callWallOI ?? null, putWallOI: inst.putWallOI ?? null,
    callWalls: topN(inst.callWalls), putWalls: topN(inst.putWalls),
    pcRatio: inst.pcRatio ?? null, totalCallOI: inst.totalCallOI ?? null, totalPutOI: inst.totalPutOI ?? null,
    totalCallChg: inst.totalCallChg ?? null, totalPutChg: inst.totalPutChg ?? null,
    gex: inst.exposures?.gex ?? null, dex: inst.exposures?.dex ?? null,
    hadChangeData: !!(inst.rawChg && String(inst.rawChg).trim()),
    savedAtMs: inst.savedAtMs ?? null,
  };
}
async function _snapshotOIHistory() {
  try {
    const raw = await kv.get('oi_store').catch(() => null);
    if (!raw) return 0;
    const store = JSON.parse(raw).data ?? JSON.parse(raw);
    if (!store || typeof store !== 'object') return 0;
    const day = _rlSessionDate(null);
    const histRaw = await kv.get('oi_history').catch(() => null);
    const hist = histRaw ? (JSON.parse(histRaw).data ?? JSON.parse(histRaw)) : {};
    let n = 0;
    for (const [pair, inst] of Object.entries(store)) {
      const summary = _oiHistorySummary(inst);
      if (!summary) continue;
      hist[pair] = hist[pair] || {};
      hist[pair][day] = summary;                                 // overwrite today (tracks the latest morning paste)
      const dates = Object.keys(hist[pair]).sort();
      for (const d of dates.slice(0, Math.max(0, dates.length - 60))) delete hist[pair][d];   // keep ~60 days
      n++;
    }
    if (!n) return 0;
    await kv.put('oi_history', JSON.stringify({ data: hist, timestamp: Date.now() }));
    console.log(`[oi-history] archived ${n} pair(s) → ${day}`);
    return n;
  } catch (e) { console.error('[oi-history] snapshot failed:', e.message); return 0; }
}
setInterval(_snapshotOIHistory, 30 * 60_000);                    // archive the day's paste periodically
setTimeout(_snapshotOIHistory, 50_000);

// History + day-over-day deltas. With ?pair= → one pair's full history + deltas
// (the card detail + AI feed). Without → EVERY pair's latest delta in one call
// (the brief page renders all cards at once). Deltas computed server-side by the
// single `oiDeltas` brick — no client re-implementation.
app.get('/api/oi-history', async (req, res) => {
  try {
    const raw = await kv.get('oi_history').catch(() => null);
    const hist = raw ? (JSON.parse(raw).data ?? JSON.parse(raw)) : {};
    const norm = s => String(s).toLowerCase().replace(/[/_]/g, '');
    const latestDelta = (perPair) => {
      const dates = Object.keys(perPair).sort();
      const cur = perPair[dates[dates.length - 1]], prev = perPair[dates[dates.length - 2]];
      const dl = (cur && prev) ? oiDeltas(cur, prev) : null;
      const spot = cur?.spot || cur?.maxPain || 0;
      const stab = (spot > 0 && dates.length >= 2)
        ? oiWallStability(dates.slice(-20).map(dt => perPair[dt]), spot * 0.002)
            .filter(w => w.daysPresent >= 1).sort((a, b) => b.daysPresent - a.daysPresent).slice(0, 6)
        : [];
      return { curDate: dates[dates.length - 1] ?? null, prevDate: dates[dates.length - 2] ?? null,
               days: dates.length, deltas: dl,
               classify: dl ? classifyOIChange(dl)?.summary ?? null : null,
               stability: stab };
    };
    const key = String(req.query.pair || '').trim();
    if (!key) {
      const pairs = {};
      for (const [k, perPair] of Object.entries(hist)) pairs[k] = latestDelta(perPair);
      return res.json({ ok: true, pairs });
    }
    const pk = Object.keys(hist).find(k => k === key || norm(k) === norm(key));
    const perPair = pk ? hist[pk] : {};
    const dates = Object.keys(perPair).sort();
    const limit = Math.min(60, parseInt(req.query.limit) || 30);
    const recent = dates.slice(-limit).map(d => ({ date: d, ...perPair[d] }));
    const { curDate, prevDate, deltas } = latestDelta(perPair);
    res.json({ ok: true, pair: pk || key, dates, history: recent, deltas, curDate, prevDate });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/oi-history/snapshot', async (_req, res) => {
  try { const n = await _snapshotOIHistory(); res.json({ ok: true, pairsArchived: n, date: _rlSessionDate(null) }); }
  catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ── OI bot PLAN producer (gamma-regime strategy → tradeable zones) ────────────
// The single planner (`buildOIZones`) run per instrument from the shared oi_store,
// injecting wall-stability + change-classification from oi_history. The zones page
// renders `oi_bot_zones` and the Python executor trades the SAME artifact (no
// drift). Universe = gold + indices by default; FX only when fx_enabled (weak
// asset). Config lives in `oi_bot_config` (bot-config OI tab, stage 2).
const OI_BOT_INDEX = ['nq', 'spx', 'dax', 'dow', 'rut'];   // canonical registry keys (resolveKey output)
const OI_BOT_UNIVERSE = ['gold', ...OI_BOT_INDEX];
const OI_BOT_CFG_DEFAULTS = {
  minTier: 'strong', slBufferPips: 15, breakPips: 20, nearExpiryDTE: 2, extendedPips: 30,
  fadeInPin: true, followBreaks: true, maxPainReversion: true,
  requireEstablished: false, avoidLiquidating: true,
  maxZonesPerSide: 4,                // bot trades the K strongest walls per side (display count is separate)
  fx_enabled: false, fx_pairs: [],   // opt-in FX universe (weak asset); [] + fx_enabled = none added
  fxFallbackTpR: 2.0,                // FX-only: give a wall-less trade (breakout past the outermost
                                     // partial-OI wall) a measured-move TP at this R-multiple of the
                                     // stop, so FX OI trades are never SL-only. 0 = leave SL-only.
  fallbackTpR: 0,                    // same for gold+indices (default off — they usually have a wall ahead)
};
function _oiBotStabilityChange(hist, key) {
  const norm = x => String(x).toLowerCase().replace(/[/_]/g, '');
  const pk = Object.keys(hist || {}).find(k => norm(k) === norm(key));
  if (!pk) return { stability: null, change: null };
  const perPair = hist[pk], dates = Object.keys(perPair).sort();
  const cur = perPair[dates[dates.length - 1]], prev = perPair[dates[dates.length - 2]];
  const dl = (cur && prev) ? oiDeltas(cur, prev) : null;
  const spot = cur?.spot || cur?.maxPain || 0;
  const stability = (spot > 0 && dates.length >= 2)
    ? oiWallStability(dates.slice(-20).map(dt => perPair[dt]), spot * 0.002) : null;
  return { stability, change: dl ? classifyOIChange(dl) : null };
}
async function _refreshOIBotZones() {
  try {
    const [oiRaw, cfgRaw, histRaw] = await Promise.all([
      kv.get('oi_store').catch(() => null), kv.get('oi_bot_config').catch(() => null), kv.get('oi_history').catch(() => null),
    ]);
    if (!oiRaw) return 0;
    const store = JSON.parse(oiRaw).data ?? JSON.parse(oiRaw);
    const cfg = { ...OI_BOT_CFG_DEFAULTS, ...(cfgRaw ? (JSON.parse(cfgRaw).data ?? JSON.parse(cfgRaw)) : {}) };
    const hist = histRaw ? (JSON.parse(histRaw).data ?? JSON.parse(histRaw)) : {};
    const universe = new Set([...OI_BOT_UNIVERSE, ...(cfg.fx_enabled ? (cfg.fx_pairs || []) : [])]);
    const instruments = {};
    for (const [pair, inst] of Object.entries(store)) {
      const key = (() => { try { return resolveKey(pair); } catch { return null; } })() || String(pair).toLowerCase().replace(/[/_]/g, '');
      if (!universe.has(key)) continue;                          // gold+indices (+ opted-in FX) only
      const pip = (() => { try { return _pipSize(key) || 0; } catch { return 0; } })() || 0.0001;
      const { stability, change } = _oiBotStabilityChange(hist, key);
      // Stale-data guard: if the live spot sits OUTSIDE the option chain's own
      // strike range, the paste is at the wrong price level (stale / mis-scaled —
      // e.g. SPX strikes ~6300 while the index is ~7540). Don't build/trade zones
      // off it — flag it so the config table shows "⚠ re-paste".
      const strikes = [...(Array.isArray(inst.callWalls) ? inst.callWalls : []),
                       ...(Array.isArray(inst.putWalls) ? inst.putWalls : [])]
        .map(w => w?.strike).filter(Number.isFinite);
      let stale = null;
      if (strikes.length >= 2 && Number.isFinite(inst.spot)) {
        const lo = Math.min(...strikes), hi = Math.max(...strikes);
        if (inst.spot < lo * 0.95 || inst.spot > hi * 1.05) {
          stale = `spot ${inst.spot} outside strike range ${lo}–${hi} — stale/mis-scaled OI, re-paste`;
        }
      }
      // FX (anything outside the gold+indices base universe) gets a measured-move TP
      // fallback so a wall-less breakout isn't left SL-only; gold/indices use their own.
      const isFx = !OI_BOT_UNIVERSE.includes(key);
      const fallbackTpR = isFx ? (cfg.fxFallbackTpR ?? 2.0) : (cfg.fallbackTpR ?? 0);
      const zones = stale ? [] : buildOIZones(inst, inst.spot, { ...cfg, pip, stability, change, fallbackTpR });
      const gex = inst.exposures?.gex ?? 0;
      instruments[key] = { spot: inst.spot ?? null, maxPain: inst.maxPain ?? null,
        regime: gex > 0 ? 'PIN' : gex < 0 ? 'BREAKOUT' : 'NEUTRAL', zones, zoneCount: zones.length, stale };
      if (stale) console.warn(`[oi-bot] ${key}: ${stale} — skipping (no zones)`);
    }
    await kv.put('oi_bot_zones', JSON.stringify({ data: { strategy: 'oi-bot', generatedAt: new Date().toISOString(), instruments }, timestamp: Date.now() }));
    const total = Object.values(instruments).reduce((a, v) => a + v.zoneCount, 0);
    console.log(`[oi-bot] zones refreshed · ${Object.keys(instruments).length} instruments · ${total} zones`);
    return Object.keys(instruments).length;
  } catch (e) { console.error('[oi-bot] zones refresh failed:', e.message); return 0; }
}
setInterval(_refreshOIBotZones, 10 * 60_000);
setTimeout(_refreshOIBotZones, 60_000);

app.get('/api/oi-bot/zones', async (req, res) => {
  try {
    const raw = await kv.get('oi_bot_zones').catch(() => null);
    const vm = raw ? (JSON.parse(raw).data ?? JSON.parse(raw)) : { instruments: {} };
    const pair = (req.query.pair || '').toLowerCase();
    if (pair) { const k = (() => { try { return resolveKey(pair); } catch { return pair; } })() || pair; return res.json({ ok: true, ...vm, instruments: { [k]: vm.instruments?.[k] || null } }); }
    res.json({ ok: true, ...vm });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});
app.post('/api/oi-bot/zones/refresh', async (_req, res) => {
  try { const n = await _refreshOIBotZones(); res.json({ ok: true, instruments: n }); }
  catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ── Give-back analytics: per-bot MFE-vs-realised from the durable trade logs.
// Answers "we run in profit intraday then end red — how, per bot?" on the
// dashboard (no Python). Rows carry mfe_pips live now (pylego brokers); older
// rows are enriched here from the M1 path via loadM1ForPair. Cached 5 min — the
// M1 walk is the only cost. ?refresh=1 forces a recompute.
let _givebackCache = { at: 0, data: null };
app.get('/api/giveback', async (req, res) => {
  try {
    if (req.query.refresh !== '1' && _givebackCache.data && Date.now() - _givebackCache.at < 5 * 60_000)
      return res.json(_givebackCache.data);
    const BOTS = [
      { id: 'range_line', label: 'Range-Line', kvKey: 'range_line_trade_log' },
      { id: 'oi',         label: 'OI Gamma',   kvKey: 'oi_bot_trade_log' },
      { id: 'confluence', label: 'Confluence', kvKey: 'confluence_trade_log' },
    ];
    const pipFor = (k) => { try { return _pipSize(k) || 0.0001; } catch { return 0.0001; } };
    const out = {};
    for (const bot of BOTS) {
      const raw = await kv.get(bot.kvKey).catch(() => null);
      const rows = raw ? (JSON.parse(raw).data ?? JSON.parse(raw)) : [];
      // Reconstruct mfe_pips for pre-logging rows from the real M1 path; group by
      // instrument key so each parquet loads once.
      const byKey = {};
      for (const r of rows) {
        if (r.mfe_pips != null || r.open_price == null || !r.time_open || !r.time_close) continue;
        const k = r.key || (() => { try { return resolveKey(r.symbol); } catch { return null; } })();
        if (k) (byKey[k] ||= []).push(r);
      }
      for (const [k, rs] of Object.entries(byKey)) {
        let packed = null; try { packed = await loadM1ForPair(k, BT_M1_DIR); } catch { packed = null; }
        if (!packed) continue;
        const pip = pipFor(k);
        for (const r of rs) {
          const e = excursionFromM1(packed, r, pip);
          if (e) { r.mfe_pips = +e.mfePips.toFixed(1); r.mae_pips = +e.maePips.toFixed(1); }
        }
      }
      out[bot.id] = { label: bot.label, ...summarizeGiveback(rows, pipFor) };
    }
    const payload = { ok: true, generatedAt: Date.now(), bots: out };
    _givebackCache = { at: Date.now(), data: payload };
    res.json(payload);
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// ── OI bot: push the planned levels + WHY to Telegram, one pretty message per
// instrument ("per chart we're trading against"). On-demand from the config page.
const _OI_ICON = { gold: '🥇', nq: '💻', spx: '🇺🇸', dow: '🏭', rut: '🐘', dax: '🇩🇪', ftse: '🇬🇧' };
const _OI_TV = { gold: 'OANDA:XAUUSD', nq: 'OANDA:NAS100USD', spx: 'OANDA:SPX500USD',
  dow: 'OANDA:US30USD', rut: 'OANDA:US2000USD', dax: 'OANDA:DE30EUR', ftse: 'OANDA:UK100GBP' };
function _oiDigits(key) { try { return instrument(key).digits; } catch { return 2; } }
function _oiFmt(key, p) { return (p == null || !Number.isFinite(+p)) ? '—' : (+p).toFixed(_oiDigits(key)); }
function _oiPlanMessage(key, inst) {
  const name = key.toUpperCase();
  const icon = _OI_ICON[key] || '💱';
  const tv = _OI_TV[key] || `OANDA:${name.replace('/', '')}`;
  const link = `<a href="https://www.tradingview.com/chart/?symbol=${tv}">${name}</a>`;
  const head = `${icon} <b>${link}</b>  ·  ${inst.regime || '—'}\n`
    + `spot <code>${_oiFmt(key, inst.spot)}</code> · max pain <code>${_oiFmt(key, inst.maxPain)}</code>`;
  const zones = Array.isArray(inst.zones) ? inst.zones : [];
  if (!zones.length) return `${head}\n<i>no planned levels</i>`;
  const body = zones.map(z => {
    const dir = z.side === 'buy' ? '🟢 ▲ <b>BUY</b>' : '🔴 ▼ <b>SELL</b>';
    const tp = z.tp1 ?? z.tp2;
    const rr = (tp != null && z.sl != null && z.entry != null && Math.abs(z.entry - z.sl) > 0)
      ? `  (${(Math.abs(tp - z.entry) / Math.abs(z.entry - z.sl)).toFixed(1)}R)` : '';
    return `${dir} · ${(z.mode || '').toUpperCase()}  @ <code>${_oiFmt(key, z.entry)}</code>\n`
      + `   SL <code>${_oiFmt(key, z.sl)}</code> · TP <code>${tp != null ? _oiFmt(key, tp) : '—'}</code>${rr}\n`
      + `   <i>${z.rationale || ''}</i>`;
  }).join('\n\n');
  return `${head}\n━━━━━━━━━━\n${body}`;
}
app.post('/api/oi-bot/broadcast', async (req, res) => {
  try {
    const [zRaw, cfgRaw, tgRaw] = await Promise.all([
      kv.get('oi_bot_zones').catch(() => null), kv.get('oi_bot_config').catch(() => null), kv.get('tg_config').catch(() => null),
    ]);
    const vm = zRaw ? (JSON.parse(zRaw).data ?? JSON.parse(zRaw)) : null;
    const instruments = vm?.instruments || {};
    const cfg = cfgRaw ? (JSON.parse(cfgRaw).data ?? JSON.parse(cfgRaw)) : {};
    const tg = tgRaw ? (JSON.parse(tgRaw).data ?? JSON.parse(tgRaw)) : {};
    const token = (cfg.tg_token || '').trim() || tg.token;
    const chatId = (cfg.tg_chat_id || '').trim() || tg.chatId;
    if (!token || !chatId) return res.status(400).json({ ok: false, error: 'No Telegram token/chat configured (OI tab or shared tg_config)' });
    const pairQ = (req.query.pair || '').toLowerCase();
    const wantKey = pairQ ? ((() => { try { return resolveKey(pairQ); } catch { return null; } })() || pairQ) : null;
    // Only instruments with planned zones (unless ?all=1), optionally one pair.
    const targets = Object.keys(instruments).filter(k =>
      (wantKey ? k === wantKey : true) && ((instruments[k]?.zones || []).length || req.query.all));
    if (!targets.length) return res.json({ ok: true, sent: 0, note: 'no instruments with planned levels' });
    await sendTelegram(token, chatId,
      `🧲 <b>OI Gamma — levels &amp; why</b>${vm?.generatedAt ? `\n<i>${new Date(vm.generatedAt).toUTCString()}</i>` : ''}`);
    let sent = 0;
    for (const k of targets) { if (await sendTelegram(token, chatId, _oiPlanMessage(k, instruments[k]))) sent++; }
    res.json({ ok: true, sent, instruments: targets });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// The forward-test audit: join the accumulated trade log against the per-date OI
// artifact → tagged-vs-untagged expectancy, per OI type, + round-number independence.
app.get('/api/range-line-bot/oi-audit', async (req, res) => {
  try {
    const [logRaw, oiRaw] = await Promise.all([
      kv.get('range_line_trade_log').catch(() => null),
      kv.get('range_line_oi').catch(() => null),
    ]);
    const log = logRaw ? (JSON.parse(logRaw).data ?? JSON.parse(logRaw)) : [];
    const oiByDate = oiRaw ? (JSON.parse(oiRaw).data ?? JSON.parse(oiRaw)) : {};
    const tolPips = (req.query.tolPips != null && req.query.tolPips !== '') ? parseFloat(req.query.tolPips) : 10;
    const audit = oiAudit(log, oiByDate, {
      pipFor: (k) => { try { return _pipSize(k) || 0; } catch { return 0; } },
      tolPips, roundTolPips: tolPips,
    });
    res.json({ ok: true, tolPips, tradesLogged: log.length, oiDates: Object.keys(oiByDate).length, audit });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Current options-OI levels per instrument, converted from the OI analyser
// output the user updates each morning (KV `oi_store`) via the shared
// `oiStoreToLevels` brick — the ONE source of truth, so the Python bots never
// re-port the conversion. Keyed by canonical instrument key so a bot joins by
// `instr.key`. LIVE (not date-bucketed): always reflects the latest paste. The
// ConfluenceBot reads this each state refresh to add OI as a scored confluence
// source (put/call walls, max pain, HVL, gamma flip). No date needed — the bot
// scores against "today's OI as it stands now".
app.get('/api/oi-levels', async (_req, res) => {
  try {
    const raw = await kv.get('oi_store').catch(() => null);
    const store = raw ? (JSON.parse(raw).data ?? JSON.parse(raw)) : {};
    const byInstrument = {};
    for (const [pair, inst] of Object.entries(store || {})) {
      const key = (() => { try { return resolveKey(pair); } catch { return null; } })()
                  || String(pair).toLowerCase().replace(/[/_]/g, '');
      const levels = oiStoreToLevels(inst);
      if (levels.length) byInstrument[key] = levels;
    }
    res.json({ ok: true, byInstrument, instruments: Object.keys(byInstrument) });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// KV persistence health — does bot config/credentials survive a redeploy? The
// bot-config page polls this to show a red banner when the backend is the ephemeral
// file store (the "account details keep being lost" failure) so it's never silent.
app.get('/api/kv-health', async (_req, res) => {
  // Live persistence check: reports whether the durable backend is active AND does a
  // real write→read→delete round-trip, plus whether the important bot config/creds
  // keys are actually in the store right now. Lets the user confirm a Save persisted
  // (vs. silently landing in the ephemeral file store that a redeploy wipes).
  try {
    const CHECK = [
      'yield_spread_config', 'yield_spread_credentials', 'yield_spread_plan',
      'volatility_bot_config', 'oi_bot_config', 'range_line_bot_config',
      'macro_equity_config', 'regime_bot_config', 'confluence_bot_config',
    ];
    const probe = await kv.probe(CHECK);
    res.json({ ok: true, ...kv.health(), ...probe });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

