// ── COG reference dump — all parsed reference forecasts, one JSON ─────────────
// GET /api/vol-forecast/reference-dump — every stored COG reference date parsed to
// { date: { INST: { vol, hl_med, hl_75, oc_med, oc_75 } } }. Feeds an offline test
// of candidate σ adjustments against COG's actual published numbers (the analysis
// runs on local price history; only COG's values need to come from KV).
app.get('/api/vol-forecast/reference-dump', async (_req, res) => {
  try {
    const idxRaw = await kv.get('vol_reference_index').catch(() => null);
    const dates = idxRaw ? JSON.parse(idxRaw).map(e => e.date).filter(Boolean).sort() : [];
    const ref = {};
    for (const d of dates) {
      const raw = await kv.get(`vol_reference_${d}`).catch(() => null);
      if (!raw) continue;
      try { ref[d] = _parseExportText(JSON.parse(raw).text); } catch { /* skip malformed */ }
    }
    res.json({ ok: true, dates: Object.keys(ref).length, ref });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// ── COG σ-overlay measure-first test ──────────────────────────────────────────
// GET /api/cog-overlay-test — for each stored COG reference date, compare OUR base
// forecast σ to COG's published σ and to a candidate reactive overlay:
//   adjusted = base + λ·(CC-HV − base)          (CC-HV = COG's close-to-close-HV method)
// plus a momentum-gated variant (blend at λ0.5 only when short/long vol > 1, i.e.
// vol rising). Reports mean|error-to-COG| for base vs each λ, per instrument, and
// returns every per-date row so it's auditable (NQ's CC-HV should track COG's NQ
// number — a built-in sanity check). λ is pre-registered, not fitted. Nothing in
// the live forecaster changes — measure-first only.
const _OVL_INST = [
  { name: 'EURUSD', oanda: 'EUR_USD',    cls: 'fx' },
  { name: 'GOLD',   oanda: 'XAU_USD',    cls: 'commodity' },
  { name: 'NQ',     oanda: 'NAS100_USD', cls: 'index' },
];
const _OVL_LAMBDAS = [0, 0.25, 0.5, 0.75, 1.0];
app.get('/api/cog-overlay-test', async (_req, res) => {
  if (!process.env.OANDA_KEY) return res.status(503).json({ ok: false, error: 'OANDA_KEY not configured' });
  try {
    const idxRaw = await kv.get('vol_reference_index').catch(() => null);
    const dates = idxRaw ? JSON.parse(idxRaw).map(e => e.date).filter(Boolean).sort() : [];
    if (!dates.length) return res.json({ ok: true, dates: 0, note: 'No COG reference data stored.' });
    const cogByDate = {};
    for (const d of dates) {
      const raw = await kv.get(`vol_reference_${d}`).catch(() => null);
      if (raw) { try { cogByDate[d] = _parseExportText(JSON.parse(raw).text); } catch { /* skip */ } }
    }
    // Per-instrument CC-HV(20) + vol-momentum(10/60) from London-aligned D1, session-
    // dated with the +1 evening rule so keys line up with the reference/archive dates.
    const sigMaps = {};
    for (const it of _OVL_INST) {
      try {
        const base = _oandaBaseMe();
        const url = `${base}/v3/instruments/${encodeURIComponent(it.oanda)}/candles?granularity=D&count=2600&price=M&dailyAlignment=0&alignmentTimezone=Europe%2FLondon`;
        const r = await fetch(url, { headers: { Authorization: `Bearer ${process.env.OANDA_KEY}` }, signal: AbortSignal.timeout(30_000) });
        if (!r.ok) { sigMaps[it.name] = {}; continue; }
        const lon = ((await r.json()).candles ?? [])
          .filter(c => c.complete !== false && c.mid)
          .map(c => { const t = new Date(c.time); if (t.getUTCHours() >= 20) t.setUTCDate(t.getUTCDate() + 1); return { date: t.toISOString().slice(0, 10), close: +c.mid.c }; })
          .filter(c => c.close > 0)
          .sort((a, b) => (a.date < b.date ? -1 : 1));
        const map = {};
        for (let i = 62; i < lon.length; i++) {
          const slice = lon.slice(0, i);   // closes strictly before lon[i].date
          const cc = _ccHvSigma(slice, { window: 20 });
          const s = _ccHvSigma(slice, { window: 10 }), l = _ccHvSigma(slice, { window: 60 });
          if (cc.volAnnual > 0 && s.volAnnual > 0 && l.volAnnual > 0) map[lon[i].date] = { cchv: cc.volAnnual, mom: s.volAnnual / l.volAnnual };
        }
        sigMaps[it.name] = map;
      } catch { sigMaps[it.name] = {}; }
    }
    const acc = {}, rows = [];
    for (const d of dates) {
      const cog = cogByDate[d]; if (!cog) continue;
      const ourRaw = await kv.get(`vol_forecast_${d}`).catch(() => null);
      if (!ourRaw) continue;
      let ours; try { ours = JSON.parse(ourRaw).instruments || {}; } catch { continue; }
      const ourUC = {}; for (const k of Object.keys(ours)) ourUC[k.toUpperCase()] = ours[k];
      for (const it of _OVL_INST) {
        const c = cog[it.name], o = ourUC[it.name], sig = sigMaps[it.name]?.[d];
        if (!c || !(c.vol > 0) || !o || !(o.vol_annual > 0) || !sig) continue;
        const base = o.vol_annual, target = c.vol, cchv = sig.cchv, mom = sig.mom;
        const baseErr = Math.abs(base - target);
        const row = { date: d, inst: it.name, cog: +target.toFixed(2), base: +base.toFixed(2), cchv: +cchv.toFixed(2), mom: +mom.toFixed(2), baseErr: +baseErr.toFixed(2) };
        for (const lam of _OVL_LAMBDAS) {
          const err = Math.abs((base + lam * (cchv - base)) - target);
          const key = `${it.name}|${lam}`;
          (acc[key] ||= { errs: [], improved: 0, n: 0 });
          acc[key].errs.push(err); acc[key].n++; if (err < baseErr - 1e-9) acc[key].improved++;
        }
        const adjG = mom > 1 ? base + 0.5 * (cchv - base) : base;
        const errG = Math.abs(adjG - target);
        (acc[`${it.name}|gated`] ||= { errs: [], improved: 0, n: 0 });
        acc[`${it.name}|gated`].errs.push(errG); acc[`${it.name}|gated`].n++; if (errG < baseErr - 1e-9) acc[`${it.name}|gated`].improved++;
        row.adjGated = +adjG.toFixed(2);
        rows.push(row);
      }
    }
    const mean = a => a.length ? a.reduce((s, v) => s + v, 0) / a.length : NaN;
    const summary = {};
    for (const it of _OVL_INST) {
      const s = { n: acc[`${it.name}|0`]?.n || 0 };
      for (const lam of _OVL_LAMBDAS) { const a = acc[`${it.name}|${lam}`]; s[`mae_l${lam}`] = a ? +mean(a.errs).toFixed(3) : null; }
      const g = acc[`${it.name}|gated`];
      s.mae_gated = g ? +mean(g.errs).toFixed(3) : null;
      s.gated_improved_pct = g && g.n ? +(100 * g.improved / g.n).toFixed(0) : null;
      summary[it.name] = s;
    }
    res.json({
      ok: true, refDates: dates.length, scoredRows: rows.length,
      note: 'mae_l0 = base error to COG; mae_l1.0 = pure-CC-HV error; gated = blend λ0.5 only when vol rising. Overlay helps if MAE drops below mae_l0 without hurting pairs that already match. λ pre-registered, not fitted. Sanity: NQ cchv≈cog.',
      summary, rows,
    });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// ── COG day-of-week weighting probe ───────────────────────────────────────────
// GET /api/cog-dow — over every stored COG reference date, compare COG's number to
// OURS (the archived forecast for that session) and group the COG/ours ratio by
// weekday. Demeaned PER INSTRUMENT so the constant σ-source gap (e.g. NQ's CC-HV)
// doesn't masquerade as a weekday effect: `rel` = (COG/ours on that weekday) ÷ (that
// instrument's overall COG/ours). rel≈1.00 on every weekday ⇒ COG applies no
// day-of-week weight; a consistent Mon<1, Wed/Thu>1 tilt across metrics ⇒ he does.
app.get('/api/cog-dow', async (_req, res) => {
  try {
    const idxRaw = await kv.get('vol_reference_index').catch(() => null);
    const dates = idxRaw ? JSON.parse(idxRaw).map(e => e.date).filter(Boolean).sort() : [];
    if (!dates.length) return res.json({ ok: true, dates: 0, note: 'No COG reference data stored yet.' });
    const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const METRICS = [['vol', 'vol_annual'], ['hl_med', 'hl_median'], ['hl_75', 'hl_75'], ['oc_med', 'oc_median'], ['oc_75', 'oc_75']];
    const rows = [];   // { metric, wd, inst, r }
    let matchedDates = 0;
    for (const d of dates) {
      const [refRaw, ourRaw] = await Promise.all([
        kv.get(`vol_reference_${d}`).catch(() => null),
        kv.get(`vol_forecast_${d}`).catch(() => null),
      ]);
      if (!refRaw || !ourRaw) continue;
      let cog, ours;
      try { cog = _parseExportText(JSON.parse(refRaw).text); } catch { continue; }
      try { ours = JSON.parse(ourRaw).instruments || {}; } catch { continue; }
      const ourUC = {}; for (const k of Object.keys(ours)) ourUC[k.toUpperCase()] = ours[k];
      const wd = new Date(d + 'T00:00:00Z').getUTCDay();
      if (wd < 1 || wd > 5) continue;
      matchedDates++;
      for (const inst of Object.keys(cog)) {
        const o = ourUC[inst], c = cog[inst];
        if (!o) continue;
        for (const [ck, ok] of METRICS) {
          const cv = c[ck], ov = o[ok];
          if (cv > 0 && ov > 0) rows.push({ metric: ck, wd, inst, r: cv / ov });
        }
      }
    }
    const mean = a => a.length ? a.reduce((s, v) => s + v, 0) / a.length : NaN;
    const byMetric = {};
    for (const [ck] of METRICS) {
      const mr = rows.filter(r => r.metric === ck);
      const instVals = {};
      for (const r of mr) (instVals[r.inst] ||= []).push(r.r);
      const instMean = {};
      for (const k in instVals) instMean[k] = mean(instVals[k]);
      const wdRel = { 1: [], 2: [], 3: [], 4: [], 5: [] };
      for (const r of mr) if (wdRel[r.wd] && instMean[r.inst] > 0) wdRel[r.wd].push(r.r / instMean[r.inst]);
      const out = { overall_cog_over_ours: mr.length ? +mean(mr.map(r => r.r)).toFixed(3) : null };
      for (const w of [1, 2, 3, 4, 5]) out[WD[w]] = { n: wdRel[w].length, rel: wdRel[w].length ? +mean(wdRel[w]).toFixed(3) : null };
      byMetric[ck] = out;
    }
    res.json({
      ok: true, refDates: dates.length, matchedDates, matchedRows: rows.length,
      note: 'rel = (COG/ours ratio on that weekday) ÷ (that instrument\'s overall COG/ours). 1.00 = no weekday weight; >1 = COG runs bigger than us on that weekday.',
      byMetric,
    });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// ── COG-level POC — COG's ACTUAL forecast levels vs ACTUAL price, on the days we
// have COG reference data for (EURUSD / NQ / GOLD). GET /api/cog-level-poc.
// Reads the stored COG exports from KV, parses each day's levels, loads that pair's
// intraday bars, and measures reversion at COG's median/75th/O-C levels. Railway
// only (KV + M1). Descriptive on however many COG days exist — not a big-N claim.
const _COG_ALIASES = { EURUSD: ['EURUSD', 'EUR/USD', 'EUR_USD'], NQ: ['NQ', 'NAS100', 'NAS100_USD', 'US100', 'NAS'], GOLD: ['GOLD', 'XAUUSD', 'XAU/USD', 'XAU_USD'] };
// Fetch OANDA M5 candles for a date range (chunked under the 5000-bar cap). The R2
// parquet lags weeks behind, so the recent COG days must come straight from OANDA.
async function _fetchOandaM5(sym, fromSec, toSec) {
  const base = (process.env.OANDA_ENV || 'live') === 'practice' ? 'https://api-fxpractice.oanda.com' : 'https://api-fxtrade.oanda.com';
  const out = [];
  // from + count (NOT from + to) — count-based paging never requests a future `to`
  // (which OANDA 400s) and stops cleanly when a short page signals end-of-data.
  let cursor = fromSec;
  for (let guard = 0; guard < 20 && cursor < toSec; guard++) {
    const url = `${base}/v3/instruments/${encodeURIComponent(sym)}/candles`
              + `?granularity=M5&price=M&from=${encodeURIComponent(new Date(cursor * 1000).toISOString())}&count=5000`;
    const r = await fetch(url, { headers: { Authorization: `Bearer ${process.env.OANDA_KEY}` }, signal: AbortSignal.timeout(30_000) });
    if (!r.ok) throw new Error(`OANDA M5 ${sym}: HTTP ${r.status}`);
    const candles = (await r.json()).candles ?? [];
    if (!candles.length) break;
    let lastSec = cursor;
    for (const c of candles) {
      const t = Math.floor(new Date(c.time).getTime() / 1000);
      lastSec = t;
      if (t > toSec) break;
      if (c.complete === false || !c.mid) continue;
      const cl = parseFloat(c.mid.c); if (!(cl > 0)) continue;
      out.push({ time: t, open: parseFloat(c.mid.o), high: parseFloat(c.mid.h), low: parseFloat(c.mid.l), close: cl });
    }
    if (lastSec <= cursor || candles.length < 5000) break;   // no progress or reached the end
    cursor = lastSec + 300;                                   // advance past the last candle (5 min)
  }
  return out;
}
app.get('/api/cog-level-poc', async (_req, res) => {
  try {
    // 1. COG reference dates (newest first, from the index).
    const idxRaw = await kv.get('vol_reference_index').catch(() => null);
    const dates = idxRaw ? JSON.parse(idxRaw).map(e => e.date).filter(Boolean) : [];
    if (!dates.length) return res.json({ ok: true, cogDates: 0, results: [], note: 'No COG reference data stored yet (paste some on vol-forecast → Ref Data).' });
    // 2. Parse each stored COG export into per-instrument levels.
    const cogByDate = {};
    for (const date of dates) {
      const raw = await kv.get(`vol_reference_${date}`).catch(() => null);
      if (!raw) continue;
      try { cogByDate[date] = _parseExportText(JSON.parse(raw).text); } catch { /* skip malformed */ }
    }
    const _cog = (date, name) => { const rec = cogByDate[date]; if (!rec) return null; for (const a of _COG_ALIASES[name]) if (rec[a]) return rec[a]; return null; };
    // 3. Per pair: fetch OANDA M5 for the COG date range (the parquet lags weeks),
    //    split into London days, match COG dates, measure.
    const PAIRS = [{ name: 'EURUSD', sym: 'EUR_USD', cls: 'fx' }, { name: 'NQ', sym: 'NAS100_USD', cls: 'index' }, { name: 'GOLD', sym: 'XAU_USD', cls: 'commodity' }];
    const cogDatesSorted = Object.keys(cogByDate).sort();
    const fromSec = Math.floor(new Date(cogDatesSorted[0] + 'T00:00:00Z').getTime() / 1000) - 2 * 86400;   // pad for the London boundary
    const toSec   = Math.floor(new Date(cogDatesSorted.at(-1) + 'T00:00:00Z').getTime() / 1000) + 2 * 86400;
    const results = [];
    for (const p of PAIRS) {
      const row = { pair: p.name };
      try {
        let pip = 0.0001; try { pip = _pipSize(p.name) || pip; } catch { /* keep default */ }
        const bars5 = await _fetchOandaM5(p.sym, fromSec, toSec);
        const lond = buildLondonDaily(bars5 || []);
        const byDate = new Map(lond.map(d => [d.date, d]));
        // Daily history for OUR forecaster (needs ≥60 prior bars). One cheap D1 call.
        const dailyD1 = await _btFetchD1(p.sym, 400).catch(() => []);
        const _ourLevels = (date) => {
          const slice = dailyD1.filter(d => d.date < date);   // strictly-before → no lookahead
          if (slice.length < 60) return null;
          try { const fc = _computeForecast(slice, p.cls); return { hl_med: fc.hl_median, hl_75: fc.hl_75, oc_med: fc.oc_median, oc_75: fc.oc_75 }; } catch { return null; }
        };
        const cogRecs = [], oursRecs = [], widthRows = [];
        const why = { notInByDate: 0, noHlMed: 0, noBars: 0 };   // why a COG date was skipped
        for (const date of Object.keys(cogByDate)) {
          const cog = _cog(date, p.name); if (!cog) continue;
          const day = byDate.get(date);
          if (!day) { why.notInByDate++; continue; }
          if (!(cog.hl_med > 0)) { why.noHlMed++; continue; }
          if (!day.bars?.length || !(day.open > 0)) { why.noBars++; continue; }
          cogRecs.push({ date, open: day.open, bars: day.bars, pip, cog });
          const ours = _ourLevels(date);
          if (ours && ours.hl_med > 0) {
            oursRecs.push({ date, open: day.open, bars: day.bars, pip, cog: ours });
            widthRows.push({ our: ours.hl_med, cog: cog.hl_med });
          }
        }
        row.pip = pip; row.cogDatesForPair = Object.keys(cogByDate).filter(d => _cog(d, p.name)).length;
        row.matchedDays = cogRecs.length;
        // Width comparison — is COG's median systematically wider than ours, and by a
        // STABLE factor (⇒ one empirical widening matches him, no weekly tweaking)?
        if (widthRows.length) {
          const ratios = widthRows.map(w => w.cog / w.our);
          const mean = a => a.reduce((s, v) => s + v, 0) / a.length;
          const rMean = mean(ratios), rStd = Math.sqrt(mean(ratios.map(r => (r - rMean) ** 2)));
          row.widthCompare = { nDays: widthRows.length,
            ourMedMeanPct: +mean(widthRows.map(w => w.our)).toFixed(3),
            cogMedMeanPct: +mean(widthRows.map(w => w.cog)).toFixed(3),
            cogOverOurMean: +rMean.toFixed(3), cogOverOurStd: +rStd.toFixed(3) };
        }
        row.debug = {
          barsLoaded: bars5?.length ?? 0, londonDays: lond.length,
          londonFirst: lond[0]?.date ?? null, londonLast: lond.at(-1)?.date ?? null,
          dailyD1Bars: dailyD1.length, ourLevelDays: oursRecs.length, skipReasons: why,
        };
        row.result = _analyzeCogLevels(cogRecs);        // COG's levels
        row.resultOurs = _analyzeCogLevels(oursRecs);   // OUR forecaster's levels, same days + measurement
      } catch (e) { row.error = e.message; }
      results.push(row);
    }
    // Top-level debug: the COG date range + a sample parsed record, to see if it's a
    // date-range mismatch (M1 doesn't cover recent COG days) or a parse/name issue.
    const firstDate = Object.keys(cogByDate)[0];
    res.json({ ok: true, generatedAt: new Date().toISOString(), cogDates: dates.length,
      debug: { cogDateRange: dates.length ? `${dates[dates.length - 1]} … ${dates[0]}` : null,
        cogDatesList: dates, sampleDate: firstDate ?? null,
        sampleCogInstruments: firstDate ? Object.keys(cogByDate[firstDate] || {}) : [],
        sampleCogEURUSD: firstDate ? (_cog(firstDate, 'EURUSD') || null) : null },
      note: 'Paired A/B — COG\'s forecaster levels vs OUR forecaster levels, SAME days + measurement. result = COG, resultOurs = ours. widthCompare = is COG systematically wider than ours, and by a stable factor (⇒ one empirical widening matches him). Small N — directional, not proof.',
      results });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Fetch OANDA D1 candles aligned to a chosen daily boundary (timezone + hour). Lets us
// test WHICH daily anchor COG uses: London 00:00 (midnight) vs London 23:00 (FX session
// open, the "is the 23:00→00:00 hour in the candle?" question) vs NY 17:00 (our default).
async function _fetchOandaD1Aligned(sym, count, tz, hour) {
  const base = (process.env.OANDA_ENV || 'live') === 'practice' ? 'https://api-fxpractice.oanda.com' : 'https://api-fxtrade.oanda.com';
  // OANDA daily granularity code is 'D' (NOT 'D1' — that 400s). dailyAlignment +
  // alignmentTimezone place the daily candle boundary at the chosen wall-clock hour/TZ.
  const url = `${base}/v3/instruments/${encodeURIComponent(sym)}/candles`
    + `?granularity=D&price=M&count=${Math.min(count, 5000)}`
    + `&alignmentTimezone=${encodeURIComponent(tz)}&dailyAlignment=${hour}`;
  const r = await fetch(url, { headers: { Authorization: `Bearer ${process.env.OANDA_KEY}` }, signal: AbortSignal.timeout(30_000) });
  if (!r.ok) { const body = await r.text().catch(() => ''); throw new Error(`OANDA D ${sym}: HTTP ${r.status}${body ? ' ' + body.slice(0, 160) : ''}`); }
  const out = [];
  for (const c of (await r.json()).candles ?? []) {
    if (c.complete === false || !c.mid) continue;
    const cl = parseFloat(c.mid.c); if (!(cl > 0)) continue;
    out.push({ t: Math.floor(new Date(c.time).getTime() / 1000), open: parseFloat(c.mid.o), high: parseFloat(c.mid.h), low: parseFloat(c.mid.l), close: cl });
  }
  return out;
}
// GET /api/cog-reverse-engineer — infer COG's vol ALGORITHM from his stored outputs, and
// test which daily ANCHOR he uses. For each COG day + instrument we recompute candidate σ
// on D1 history strictly before the date, under THREE daily boundaries, then check which
// (anchor, estimator) reproduces his PUBLISHED annualized vol (ratio ≈ 1), and reconstruct
// his levels from his own vol × the back-solved COG constants. Railway only (KV + OANDA).
app.get('/api/cog-reverse-engineer', async (_req, res) => {
  try {
    const idxRaw = await kv.get('vol_reference_index').catch(() => null);
    const dates = idxRaw ? JSON.parse(idxRaw).map(e => e.date).filter(Boolean) : [];
    if (!dates.length) return res.json({ ok: true, cogDates: 0, results: [], note: 'No COG reference data stored yet.' });
    const cogByDate = {};
    for (const date of dates) {
      const raw = await kv.get(`vol_reference_${date}`).catch(() => null);
      if (!raw) continue;
      try { cogByDate[date] = _parseExportText(JSON.parse(raw).text); } catch { /* skip malformed */ }
    }
    const _cog = (date, name) => { const rec = cogByDate[date]; if (!rec) return null; for (const a of _COG_ALIASES[name]) if (rec[a]) return rec[a]; return null; };
    const PAIRS = [{ name: 'EURUSD', sym: 'EUR_USD', cls: 'fx' }, { name: 'NQ', sym: 'NAS100_USD', cls: 'index' }, { name: 'GOLD', sym: 'XAU_USD', cls: 'commodity' }];
    // The three daily anchors to test (owner confirmed London TZ; open question = 00:00 vs 23:00).
    const ANCHORS = [
      { key: 'lon00', tz: 'Europe/London', hour: 0, label: 'London 00:00 (midnight → midnight)' },
      { key: 'lon23', tz: 'Europe/London', hour: 23, label: 'London 23:00 (FX session open → includes the 23:00-00:00 hour)' },
      { key: 'ny17', tz: 'America/New_York', hour: 17, label: 'NY 17:00 (OANDA default / our current)' },
    ];
    const _sigmaSeries = (bars, cls) => {
      const logret = bars.map((b, i) => i ? Math.log(b.close / bars[i - 1].close) : 0);
      const omega = _ASSET_PARAMS[cls]?.garch_omega ?? 4.76e-6;
      const hv20 = _hvVarSeries(logret, 20), hv30 = _hvVarSeries(logret, 30);
      const e94 = _ewmaVarSeries(logret, 0.94), e90 = _ewmaVarSeries(logret, 0.90);
      const yz30 = _yzVolSeries(bars, 30), garch = _garchSigmas(bars, omega);
      return j => ({ hv20: Math.sqrt(hv20[j]), hv30: Math.sqrt(hv30[j]), ewma94: Math.sqrt(e94[j]), ewma90: Math.sqrt(e90[j]), yz30: yz30[j], garch: garch[j] });
    };
    const results = [];
    for (const p of PAIRS) {
      const row = { pair: p.name, anchors: [] };
      try {
        for (const a of ANCHORS) {
          try {
            const daily = await _fetchOandaD1Aligned(p.sym, 800, a.tz, a.hour);
            if (daily.length < 60) { row.anchors.push({ key: a.key, label: a.label, error: `only ${daily.length} D1 bars` }); continue; }
            const sigAt = _sigmaSeries(daily, p.cls);
            const recs = [];
            for (const date of Object.keys(cogByDate)) {
              const cog = _cog(date, p.name); if (!cog || !(cog.hl_med > 0)) continue;
              const cutoff = _btLondonMidnightSec(new Date(date + 'T12:00:00Z'));   // London midnight of the COG date
              let j = -1; for (let i = 0; i < daily.length; i++) { if (daily[i].t < cutoff) j = i; else break; }
              if (j < 30) continue;
              const sigmas = sigAt(j);
              if (!(sigmas.yz30 > 0)) continue;
              recs.push({ date, cog, sigmas });
            }
            const result = _cogReverseEngineer(recs);
            row.anchors.push({ key: a.key, label: a.label, matchedDays: recs.length, result });
          } catch (e) { row.anchors.push({ key: a.key, label: a.label, error: e.message }); }
        }
        // Best anchor = the one whose best estimator's σ reproduces his PUBLISHED vol
        // most exactly (ratioMean closest to 1). That is the daily boundary COG uses.
        const scored = row.anchors.filter(x => x.result?.bestVol).map(x => ({ key: x.key, dev: Math.abs((x.result.bestVol.ratioMean ?? 99) - 1) }));
        row.bestAnchor = scored.sort((u, v) => u.dev - v.dev)[0]?.key ?? null;
        row.matchedDays = row.anchors.find(x => x.result)?.matchedDays ?? 0;
      } catch (e) { row.error = e.message; }
      results.push(row);
    }
    res.json({ ok: true, generatedAt: new Date().toISOString(), cogDates: dates.length,
      cogConst: _COG_CONST,
      note: 'Tests which daily ANCHOR (London 00:00 vs London 23:00 vs NY 17:00) reproduces COG\'s published annualized vol, then infers his σ estimator + reconstructs his levels from his own vol × the back-solved constants. bestAnchor = the boundary whose best estimator matches his vol (ratio≈1). Small N — directional, not proof. Identifies/reproduces his line; does NOT create edge.',
      results });
  } catch (e) { res.status(500).json({ ok: false, error: e.message }); }
});

// Parse plain-text forecast export (our format or reference) into { instrumentName: {vol,hl_med,hl_75,oc_med,oc_75} }
function _parseExportText(text) {
  const result = {};
  let cur = null;
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    const hdr = line.match(/^────\s+(\S+)\s+─/);
    if (hdr) { cur = hdr[1]; result[cur] = {}; continue; }
    if (!cur) continue;
    const vol = line.match(/Volatility.*?:\s*([\d.]+)%/);
    if (vol) { result[cur].vol = parseFloat(vol[1]); continue; }
    const hl = line.match(/High to Low.*?:\s*([\d.]+)%.*?([\d.]+)%/);
    if (hl) { result[cur].hl_med = parseFloat(hl[1]); result[cur].hl_75 = parseFloat(hl[2]); continue; }
    const oc = line.match(/Open to Close.*?:\s*([\d.]+)%.*?([\d.]+)%/);
    if (oc) { result[cur].oc_med = parseFloat(oc[1]); result[cur].oc_75 = parseFloat(oc[2]); }
  }
  return result;
}

// GET /api/vol-forecast/compare/:date  — our archived forecast vs saved reference side-by-side
// Includes GARCH and Yang-Zhang shadow columns so both estimators can be compared to reference.
app.get('/api/vol-forecast/compare/:date', async (req, res) => {
  try {
    const date = req.params.date;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ ok: false, error: 'date must be YYYY-MM-DD' });

    const [ourRaw, refRaw] = await Promise.all([
      kv.get(`vol_forecast_${date}`).catch(() => null),
      kv.get(`vol_reference_${date}`).catch(() => null),
    ]);

    if (!ourRaw && !refRaw) return res.status(404).json({ ok: false, error: `No data found for ${date}` });

    const ourFc   = ourRaw ? JSON.parse(ourRaw) : null;
    const refData = refRaw ? JSON.parse(refRaw) : null;
    const refInst = refData ? _parseExportText(refData.text) : {};

    // Compute shadow estimators from cached OHLC bars (populated by runVolForecast).
    // All three use BM percentile constants — no empirical correction.
    const BM_P50 = 1.572, HN_P50 = 0.6745, TD = 252;
    const r2 = x => Math.round(x * 100) / 100;
    function _fromCache(name, seriesFn) {
      const bars = forecastState.ohlcCache?.[name];
      if (!bars?.length) return null;
      const s = seriesFn(bars);
      const sig = s.at(-1);
      if (sig == null) return null;
      const pct = sig * 100;
      return { vol: r2(pct * Math.sqrt(TD)), hl: r2(BM_P50 * pct), oc: r2(HN_P50 * pct) };
    }

    // Build per-instrument comparison rows
    const rows = [];
    const ourInst = ourFc?.instruments ?? {};
    const allNames = new Set([...Object.keys(ourInst), ...Object.keys(refInst)]);

    for (const name of allNames) {
      const o   = ourInst[name];
      const r   = refInst[name];
      const gap = (ours, refs) => (ours && refs) ? Math.round((refs / ours - 1) * 1000) / 10 : null;
      // Prefer stored shadow fields; fall back to live compute from ohlcCache.
      const yzCache     = (o?.yz_vol_annual     != null) ? null : _fromCache(name, yangZhangVolSeries);
      const hvCache     = (o?.hv_vol_annual     != null) ? null : _fromCache(name, hv20Series);
      const ewmaCache   = (o?.ewma_vol_annual   != null) ? null : _fromCache(name, ewmaVolSeries);
      // legacy_vol_annual is stored by the scheduler on each run; no on-demand fallback
      // (rsEwmaVolSeries / garch11VolSeries are internal to volForecast.js, not exported).
      const legacyCache = null;
      const yzVol     = o?.yz_vol_annual     ?? yzCache?.vol     ?? null;
      const yzHl      = o?.yz_hl_median      ?? yzCache?.hl      ?? null;
      const yzOc      = o?.yz_oc_median      ?? yzCache?.oc      ?? null;
      const hvVol     = o?.hv_vol_annual     ?? hvCache?.vol     ?? null;
      const hvHl      = o?.hv_hl_median      ?? hvCache?.hl      ?? null;
      const hvOc      = o?.hv_oc_median      ?? hvCache?.oc      ?? null;
      const ewmaVol   = o?.ewma_vol_annual   ?? ewmaCache?.vol   ?? null;
      const ewmaHl    = o?.ewma_hl_median    ?? ewmaCache?.hl    ?? null;
      const ewmaOc    = o?.ewma_oc_median    ?? ewmaCache?.oc    ?? null;
      const legacyVol = o?.legacy_vol_annual ?? legacyCache?.vol ?? null;
      const legacyHl  = o?.legacy_hl_median  ?? legacyCache?.hl  ?? null;
      const legacyOc  = o?.legacy_oc_median  ?? legacyCache?.oc  ?? null;
      rows.push({
        name,
        our: o ? {
          vol: o.vol_annual, hl_med: o.hl_median, hl_75: o.hl_75, oc_med: o.oc_median, oc_75: o.oc_75,
          yz_vol: yzVol,     yz_hl: yzHl,     yz_oc: yzOc,
          hv_vol: hvVol,     hv_hl: hvHl,     hv_oc: hvOc,
          ewma_vol: ewmaVol, ewma_hl: ewmaHl, ewma_oc: ewmaOc,
          legacy_vol: legacyVol, legacy_hl: legacyHl, legacy_oc: legacyOc,
        } : null,
        ref:  r ?? null,
        gaps: (o && r) ? {
          vol:    gap(o.vol_annual, r.vol),
          hl_med: gap(o.hl_median,  r.hl_med),
          hl_75:  gap(o.hl_75,      r.hl_75),
          oc_med: gap(o.oc_median,  r.oc_med),
          oc_75:  gap(o.oc_75,      r.oc_75),
          yz_vol:     yzVol     != null ? gap(yzVol,     r.vol)    : null,
          yz_hl:      yzHl      != null ? gap(yzHl,      r.hl_med) : null,
          yz_oc:      yzOc      != null ? gap(yzOc,      r.oc_med) : null,
          hv_vol:     hvVol     != null ? gap(hvVol,     r.vol)    : null,
          hv_hl:      hvHl      != null ? gap(hvHl,      r.hl_med) : null,
          hv_oc:      hvOc      != null ? gap(hvOc,      r.oc_med) : null,
          ewma_vol:   ewmaVol   != null ? gap(ewmaVol,   r.vol)    : null,
          ewma_hl:    ewmaHl    != null ? gap(ewmaHl,    r.hl_med) : null,
          ewma_oc:    ewmaOc    != null ? gap(ewmaOc,    r.oc_med) : null,
          legacy_vol: legacyVol != null ? gap(legacyVol, r.vol)    : null,
          legacy_hl:  legacyHl  != null ? gap(legacyHl,  r.hl_med) : null,
          legacy_oc:  legacyOc  != null ? gap(legacyOc,  r.oc_med) : null,
        } : null,
      });
    }

    res.json({
      ok: true, date,
      our_label: ourFc?.session_label ?? date,
      ref_saved_at: refData?.saved_at ?? null,
      rows,
    });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

// Session audit — retrieve a saved end-of-day session snapshot from KV.
// GET /api/vol-forecast/audit/:date  (date = YYYY-MM-DD, defaults to today)
app.get('/api/vol-forecast/audit/:date?', async (req, res) => {
  try {
    const date = req.params.date ?? new Date().toISOString().split('T')[0];
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ ok: false, error: 'date must be YYYY-MM-DD' });
    const raw = await kv.get(`vol_session_${date}`);
    if (!raw) return res.status(404).json({ ok: false, error: `No session audit found for ${date}` });
    res.json({ ok: true, date, ...JSON.parse(raw) });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message });
  }
});

function _fmtExtendedText(data) {
  const LW  = 29;
  const div = n => { const p = `──── ${n} `; return p + '─'.repeat(Math.max(0, LW - p.length)); };
  const f2  = v => (v != null ? v.toFixed(2) : '—');
  const lines = ['**VOL & RANGE FORECAST — EXTENDED**', `**For session: ${data.session_label}**`, ''];
  for (const [name, f] of Object.entries(data.instruments ?? {})) {
    const pct = f.vol_pct != null ? `  [${f.vol_pct}th percentile]` : '';
    lines.push(
      div(name),
      `Volatility (annualized) : ${f.vol_annual.toFixed(2)}%${pct}`,
      '',
      `High to Low range       : ${f2(f.hl_median)}% median · ${f2(f.hl_75)}% 75th`,
      `Open to Close move      : ${f2(f.oc_median)}% median · ${f2(f.oc_75)}% 75th`,
      `Open to High (up leg)   : ${f2(f.oh_median)}% median · ${f2(f.oh_75)}% 75th`,
      `Open to Low  (down leg) : ${f2(f.ol_median)}% median · ${f2(f.ol_75)}% 75th`,
      `5-Day  H-L (week)       : ${f2(f.hl_5d)}% median`,
      `5-Day  O-C (week)       : ${f2(f.oc_5d)}% median`,
      `20-Day H-L (month)      : ${f2(f.hl_20d)}% median`,
      `20-Day O-C (month)      : ${f2(f.oc_20d)}% median`,
      '',
    );
  }
  return lines.join('\n');
}

// Extended forecast export — vol percentile, O-H/O-L legs, weekly and monthly ranges.
app.get('/api/vol-forecast/extended/export', (_req, res) => {
  if (!forecastState.latest) {
    return res.status(202).type('text/plain').send('Forecast not yet available — check back in 60s.');
  }
  res.type('text/plain').send(_fmtExtendedText(forecastState.latest));
});

