// ── Max Copier strategy backtester (M1 event engine; runs off local/R2 parquet,
//    no OANDA D1 needed). Three exit modes A/B'd on the same signals, IS/OOS. ──
const maxCopierJobs = new Map();
function _purgeStaleMaxCopierJobs() {
  const cutoff = Date.now() - 60 * 60_000; // 1h TTL
  for (const [id, job] of maxCopierJobs) if (job.startedAt < cutoff) maxCopierJobs.delete(id);
}

function _parseMaxCopierOpts(b) {
  const num = (v, d) => (v === undefined || v === '' || isNaN(+v) ? d : +v);
  const D = MAXCOPIER_DEFAULTS;
  return {
    donchianLookback: Math.round(num(b.donchianLookback, D.donchianLookback)),
    impulseAtrMult:   num(b.impulseAtrMult, D.impulseAtrMult),
    consolBars:       Math.round(num(b.consolBars, D.consolBars)),
    consolMaxAtr:     num(b.consolMaxAtr, D.consolMaxAtr),
    vaDepth:          Math.min(Math.max(num(b.vaDepth, D.vaDepth), 0.05), 0.5),
    entryTimeout:     Math.round(num(b.entryTimeout, D.entryTimeout)),
    stopAtrBuffer:    num(b.stopAtrBuffer, D.stopAtrBuffer),
    requireDivergence: b.requireDivergence === undefined ? D.requireDivergence : !!b.requireDivergence,
    divergenceSource: b.divergenceSource === 'rsi' ? 'rsi' : 'wavetrend',
    nPositions:       Math.min(Math.max(Math.round(num(b.nPositions, D.nPositions)), 1), 10),
    maxHoldBarsM15:   Math.round(num(b.maxHoldBarsM15, D.maxHoldBarsM15)),
    tpR:              num(b.tpR, D.tpR),
    mmMult:           num(b.mmMult, D.mmMult),
    ladderR:          num(b.ladderR, D.ladderR),
    trailAtrMult:     num(b.trailAtrMult, D.trailAtrMult),
    trailStartR:      num(b.trailStartR, D.trailStartR),
    oosFrac:          Math.min(Math.max(num(b.oosFrac, D.oosFrac), 0.1), 0.6),
  };
}

app.post('/api/max-copier/run', express.json({ limit: '256kb' }), (req, res) => {
  const b = req.body ?? {};
  const opts = _parseMaxCopierOpts(b);

  const pair = b.pair ? String(b.pair).toLowerCase() : '';
  const instruments = pair && MAXCOPIER_INSTRUMENTS.includes(pair)
    ? [pair] : MAXCOPIER_INSTRUMENTS;

  const jobId     = `mc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  _purgeStaleMaxCopierJobs();
  maxCopierJobs.set(jobId, { status: 'running', startedAt });

  (async () => {
    try {
      const { results, pooled, log } = await runMaxCopierSuite(opts, instruments);
      if (!results.length) {
        maxCopierJobs.set(jobId, { status: 'error', error: 'No results generated (no M1 data reachable?)', log, startedAt });
        return;
      }
      maxCopierJobs.set(jobId, { status: 'done', result: { results, pooled, log, opts, exitModes: MAXCOPIER_EXIT_MODES }, startedAt });
    } catch (e) {
      const msg = e?.message || String(e) || 'Unknown engine error';
      console.error('[max-copier/run]', msg, e?.stack ?? '');
      maxCopierJobs.set(jobId, { status: 'error', error: msg, startedAt });
    }
  })();

  res.json({ ok: true, jobId });
});

app.get('/api/max-copier/status/:jobId', (req, res) => {
  const job = maxCopierJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running') {
    return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - job.startedAt) / 1000) });
  }
  if (job.status === 'done') return res.json({ ok: true, status: 'done', ...job.result });
  return res.status(500).json({ ok: false, status: 'error', error: job.error, log: job.log });
});

// Chart-replay trace for ONE instrument over a window (shares the job Map + the
// /status endpoint above — the client knows whether it asked for a suite or trace).
app.post('/api/max-copier/trace', express.json({ limit: '256kb' }), (req, res) => {
  const b = req.body ?? {};
  const pair = String(b.pair || '').toLowerCase();
  if (!MAXCOPIER_INSTRUMENTS.includes(pair)) {
    return res.status(400).json({ ok: false, error: `pair must be one of the 26 instruments (got "${pair}")` });
  }
  const opts = _parseMaxCopierOpts(b);
  const mode = MAXCOPIER_EXIT_MODES.includes(b.mode) ? b.mode : 'fixed_r';
  const window = { fromDate: b.fromDate || '', toDate: b.toDate || '', mode };

  const jobId = `mct_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  _purgeStaleMaxCopierJobs();
  maxCopierJobs.set(jobId, { status: 'running', startedAt });

  (async () => {
    try {
      const trace = await traceMaxCopierPair(pair, opts, window);
      if (trace.error) { maxCopierJobs.set(jobId, { status: 'error', error: trace.error, startedAt }); return; }
      maxCopierJobs.set(jobId, { status: 'done', result: { trace }, startedAt });
    } catch (e) {
      const msg = e?.message || String(e) || 'trace error';
      console.error('[max-copier/trace]', msg, e?.stack ?? '');
      maxCopierJobs.set(jobId, { status: 'error', error: msg, startedAt });
    }
  })();

  res.json({ ok: true, jobId });
});

// ── Strategy Lab — the spec-driven gauntlet backtester ───────────────────────
// Runs the 12 famous retail strategies (+ buy&hold benchmark + tsmom incumbent)
// as SPECS through one honest code path: close-only signals, costs on turnover,
// one shared chronological split date, deflated Sharpe across every variant
// tried. Pure engine js/strategyLabEngine.js; data fetched here via OANDA D1.
// Same async-job pattern as vol-backtest-v2.
const LAB_DEFAULT_UNIVERSE = [
  'EUR_USD', 'GBP_USD', 'USD_JPY', 'AUD_USD', 'USD_CAD', 'USD_CHF', 'NZD_USD',
  'XAU_USD', 'NAS100_USD', 'SPX500_USD',
];
const LAB_ALLOWED_INSTRUMENTS = new Set([
  ...LAB_DEFAULT_UNIVERSE,
  'EUR_GBP', 'EUR_JPY', 'GBP_JPY', 'AUD_JPY', 'EUR_AUD', 'EUR_CHF', 'AUD_NZD',
  'XAG_USD', 'US30_USD', 'DE30_EUR', 'UK100_GBP', 'JP225_USD', 'BCO_USD', 'WTICO_USD',
]);
const _labJobs = new Map();
function _purgeStaleLabJobs() {
  const cutoff = Date.now() - 60 * 60_000;
  for (const [id, job] of _labJobs) if (job.startedAt < cutoff) _labJobs.delete(id);
}

app.post('/api/strategy-lab/run', express.json({ limit: '64kb' }), (req, res) => {
  if (!process.env.OANDA_KEY) {
    return res.status(500).json({ ok: false, error: 'OANDA_KEY not set — cannot fetch D1 data (runs on Railway)' });
  }
  const b = req.body ?? {};
  const universe = (Array.isArray(b.universe) && b.universe.length ? b.universe : LAB_DEFAULT_UNIVERSE)
    .map(s => String(s).toUpperCase().trim())
    .filter(s => LAB_ALLOWED_INSTRUMENTS.has(s))
    .slice(0, 20);
  if (!universe.length) return res.status(400).json({ ok: false, error: 'no valid instruments in universe' });
  const opts = {
    direction: b.direction === 'longshort' ? 'longshort' : 'longflat',
    costBp: Math.min(Math.max(Number(b.costBp) || 2, 0), 50),
    oosFrac: Math.min(Math.max(Number(b.oosFrac) || 0.3, 0.1), 0.6),
    sweep: b.sweep !== false,
  };
  const specs = Array.isArray(b.signals) && b.signals.length
    ? _GAUNTLET_SPECS.filter(s => s.benchmark || b.signals.includes(s.signal))
    : _GAUNTLET_SPECS;

  const jobId = `lab_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  _purgeStaleLabJobs();
  _labJobs.set(jobId, { status: 'running', startedAt });

  (async () => {
    try {
      const markets = [], skipped = [];
      for (const sym of universe) {
        try {
          const bars = await _btFetchD1(sym, 5000);
          if (bars && bars.length >= 400) markets.push({ symbol: sym, bars });
          else skipped.push(`${sym} (${bars?.length ?? 0} bars)`);
        } catch (e) { skipped.push(`${sym} (${e.message})`); }
      }
      if (markets.length < 2) {
        _labJobs.set(jobId, { status: 'error', error: `only ${markets.length} markets fetched`, log: skipped, startedAt });
        return;
      }
      const result = _runStrategyGauntlet(markets, specs, opts);
      result.skipped = skipped;
      _labJobs.set(jobId, { status: 'done', result, startedAt });
    } catch (e) {
      const msg = e?.message || String(e) || 'Unknown engine error';
      console.error('[strategy-lab/run]', msg, e?.stack ?? '');
      _labJobs.set(jobId, { status: 'error', error: msg, startedAt });
    }
  })();

  res.json({ ok: true, jobId });
});

app.get('/api/strategy-lab/status/:jobId', (req, res) => {
  const job = _labJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running') {
    return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - job.startedAt) / 1000) });
  }
  if (job.status === 'done') return res.json({ ok: true, status: 'done', result: job.result });
  return res.status(500).json({ ok: false, status: 'error', error: job.error, log: job.log });
});

