// ── Macro-Conditioner — does the risk regime add to day-character BEYOND σ? ───
//    The honest question, NOT "fade here": holding forecast σ fixed (tercile
//    bucket), does macroCore's VIX+HY risk regime still move the day's character
//    (expansion rate / day-efficiency)? Flat within a bucket ⇒ REDUNDANT with σ
//    (the expected null); separates ⇒ a real INCREMENTAL state signal. Async job
//    over FX majors; pools rows for the pooled-FX verdict. FRED VIX+HY joined by
//    London date via macroContextByDate (publication-lag honest, frozen thresholds).
const macroCondJobs = new Map();
const _MCOND_MAJORS = ['EURUSD', 'GBPUSD', 'AUDUSD', 'NZDUSD', 'USDCAD', 'USDCHF', 'USDJPY'];
app.post('/api/macro-conditioner/run', express.json({ limit: '16kb' }), (req, res) => {
  if (!process.env.OANDA_KEY) return res.status(500).json({ ok: false, error: 'OANDA_KEY not set' });
  if (!process.env.FRED_KEY)  return res.status(500).json({ ok: false, error: 'FRED_KEY not set' });
  const { pair = '', isFrac, minSpread, minN } = req.body || {};
  let insts = WBT_INSTRUMENTS.filter(i => _MCOND_MAJORS.includes(i.name));
  if (pair) insts = insts.filter(i => i.name === pair.toUpperCase());
  if (!insts.length) return res.status(400).json({ ok: false, error: `Unknown pair: ${pair}` });
  const jobId = `mcond_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  for (const [id, j] of macroCondJobs) if (j.startedAt < Date.now() - 60 * 60_000) macroCondJobs.delete(id);
  macroCondJobs.set(jobId, { status: 'running', startedAt });
  const opts = {
    isFrac:    Number.isFinite(+isFrac)    ? +isFrac    : 0.5,
    minSpread: Number.isFinite(+minSpread) ? +minSpread : 0.05,
    minN:      Number.isFinite(+minN)      ? +minN      : 30,
    assetClass: 'fx',
  };
  (async () => {
    const perPair = {}, log = [];
    try {
      // 1) FRED VIX + HY → macroCore fredHistory shape ({ vix:[{date,value}…asc], hy:[…] })
      //    Both are DAILY business-day series since 2010 (~4000 obs expected). A short
      //    response (partial FRED read) truncates the regime window and silently biases
      //    the whole test, so fetch with a size-sanity retry and LOG each series' span.
      const fromDate = '2010-01-01';
      const _fetchFredSane = async (sid, minObs) => {
        let m = await fetchFredSeries(sid, fromDate, process.env.FRED_KEY);
        if (m.size < minObs) {                            // suspiciously short → one retry
          log.push(`FRED ${sid}: only ${m.size} obs (<${minObs}) — retrying once`);
          try { const m2 = await fetchFredSeries(sid, fromDate, process.env.FRED_KEY); if (m2.size > m.size) m = m2; } catch { /* keep first */ }
        }
        return m;
      };
      const vixMap = await _fetchFredSane(_MACRO_FRED_SERIES.vix, 1500);
      const hyMap  = await _fetchFredSane(_MACRO_FRED_SERIES.hy,  1500);
      const toArr = m => [...m.entries()].sort((a, b) => a[0] < b[0] ? -1 : 1).map(([date, value]) => ({ date, value }));
      const fredHistory = { vix: toArr(vixMap), hy: toArr(hyMap) };
      const span = a => a.length ? `${a[0].date}→${a[a.length - 1].date}` : 'none';
      log.push(`FRED vix: ${fredHistory.vix.length} obs (${span(fredHistory.vix)}) · hy: ${fredHistory.hy.length} obs (${span(fredHistory.hy)})`);
      if (fredHistory.hy.length < 1500 || fredHistory.vix.length < 1500)
        log.push('⚠ short FRED series — regime window is truncated; verdict may read INSUFFICIENT_COVERAGE (a broken join, not a null).');
      // 2) regime map — market-wide (VIX+HY), so compute ONCE and reuse for every pair.
      const ctxByDate = _macroContextByDate('EURUSD', fredHistory, { to: Date.now() });
      const regimeByDate = {};
      for (const [d, v] of Object.entries(ctxByDate)) regimeByDate[d] = v.macro.regime;
      const regDates = Object.keys(regimeByDate).sort();
      const nOff = Object.values(regimeByDate).filter(r => r === 'RISK_OFF').length;
      log.push(`regime days ${regDates.length} (${regDates[0] || '—'}→${regDates[regDates.length - 1] || '—'}) · risk-off ${nOff}`);
      // 3) per pair: London-daily + causal σ + join regime → σ-controlled conditional
      const pooledRows = [];
      for (const cfg of insts) {
        try {
          const { bars, src } = await _intradayForAB(cfg);
          const daily = buildLondonDaily(bars);
          if (daily.length < 150) { log.push(`${cfg.name}: only ${daily.length} daily bars`); continue; }
          const sig = _volSigmaSeries(daily, 'fx');
          const series = {
            date:  daily.map(d => d.date),  open: daily.map(d => d.open),
            high:  daily.map(d => d.high),  low:  daily.map(d => d.low),
            close: daily.map(d => d.close), sigma: Array.from(sig),
          };
          const r = _mcondAnalyzePair(series, regimeByDate, opts);
          if (r.insufficient) { log.push(`${cfg.name}: insufficient (${r.nDays}d regime-covered)`); continue; }
          pooledRows.push(...r._rows); delete r._rows;      // pool, then strip from wire payload
          r.src = src; perPair[cfg.name] = r;
          const cov = r.coverage;
          log.push(`${cfg.name}: ${r.nDays}d covered / ${cov.priceDays}d price (${Math.round(cov.coveredFrac * 100)}%, ${cov.firstRegimeDate}→${cov.lastRegimeDate}) · ${r.verdict.label} (${r.verdict.bucketsAgreeing}/${r.verdict.bucketsEvaluable} agree/eval) · src ${src}`);
        } catch (e) { log.push(`${cfg.name}: ${e?.message}`); }
      }
      const names = Object.keys(perPair);
      if (!names.length) { macroCondJobs.set(jobId, { status: 'error', error: 'No pairs evaluated', log, startedAt }); return; }
      const pooledSummary = _mcondSummarize(pooledRows);
      const pooledDates = pooledRows.map(r => r.date).sort();
      const pooledCoverage = { regimeDays: pooledRows.length, firstRegimeDate: pooledDates[0] || null, lastRegimeDate: pooledDates[pooledDates.length - 1] || null };
      const pooled = { nDays: pooledRows.length, summary: pooledSummary, verdict: _mcondVerdict(pooledSummary, opts), coverage: pooledCoverage };
      log.push(`POOLED FX: ${pooledRows.length}d · ${pooled.verdict.label} (${pooled.verdict.bucketsAgreeing}/${pooled.verdict.bucketsEvaluable} σ-buckets agree/evaluable)`);
      macroCondJobs.set(jobId, { status: 'done', startedAt, result: { ok: true, ...opts, perPair, pooled, pairs: names, log } });
    } catch (e) { macroCondJobs.set(jobId, { status: 'error', error: e?.message || String(e), log, startedAt }); }
  })();
  res.json({ ok: true, jobId });
});
app.get('/api/macro-conditioner/status/:jobId', (req, res) => {
  const job = macroCondJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running') return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - job.startedAt) / 1000) });
  if (job.status === 'done') return res.json({ ok: true, status: 'done', ...job.result });
  return res.status(500).json({ ok: false, status: 'error', error: job.error, log: job.log });
});

// ── News-Exhaustion — does the economic calendar predict fade vs follow? ───────
// Buckets each session by in-session news (Major/minor/none) for the pair's
// currencies, then measures reached-75% + fade/follow expectancy per bucket,
// IS/OOS. The calendar (calendar_events.csv, on disk) is parsed once + cached.
const newsJobs = new Map();
const _NEWS_CAL = { events: null };
function _loadNewsCalendar() {
  if (_NEWS_CAL.events) return _NEWS_CAL.events;
  const p = path.join(__dirname, 'calendar_events.csv');
  if (!fs.existsSync(p)) throw new Error('calendar_events.csv not found on disk');
  _NEWS_CAL.events = _parseCalendarCsv(fs.readFileSync(p, 'utf8'));
  return _NEWS_CAL.events;
}
// Historical calendar events for chart overlays (forecast-path.html news
// markers): the on-disk CSV (2014→its refresh date), topped up past the CSV's
// tail with the LIVE week feed (econCalendar brick, 30-min cached) so the
// live-edge cone still shows upcoming releases. Filtered by date range / pair
// currencies / minimum impact rank (3 = Major).
const _CAL_COUNTRY_TO_CCY = { US: 'USD', EU: 'EUR', GB: 'GBP', JP: 'JPY', AU: 'AUD', NZ: 'NZD', CA: 'CAD', CH: 'CHF', CN: 'CNY' };
const _CAL_IMPACT_RANK = { high: 3, medium: 2, low: 1 };
app.get('/api/calendar-events', async (req, res) => {
  try {
    const events = _loadNewsCalendar();
    const { from, to, pair = '', minRank = '2' } = req.query;
    const ccys = pair ? _calPairCurrencies(pair) : null;
    const fromMs = from ? Date.parse(from + 'T00:00:00Z') : -Infinity;
    const toMs = to ? Date.parse(to + 'T23:59:59Z') : Infinity;
    const mr = Number(minRank) || 0;
    const out = events.filter(e => e.ms >= fromMs && e.ms <= toMs && e.rank >= mr && (!ccys || ccys.has(e.ccy)))
      .map(e => ({ ms: e.ms, ccy: e.ccy, rank: e.rank, event: e.event }));

    const csvLastMs = events.length ? events[events.length - 1].ms : 0;
    if (toMs > csvLastMs) {
      try {
        const wk = await _fetchWeekEvents({ finnhubKey: process.env.FINNHUB_KEY || process.env.FINHUB_KEY });
        for (const e of (wk?.events ?? [])) {
          if (!(e.ms > csvLastMs && e.ms >= fromMs && e.ms <= toMs)) continue;
          const ccy = _CAL_COUNTRY_TO_CCY[e.country] ?? e.country;
          const rank = _CAL_IMPACT_RANK[e.impact] ?? 0;
          if (rank >= mr && (!ccys || ccys.has(ccy))) out.push({ ms: e.ms, ccy, rank, event: e.event });
        }
        out.sort((a, b) => a.ms - b.ms);
      } catch { /* dead live feed ⇒ CSV-only markers, never an error */ }
    }
    res.json({ ok: true, n: out.length, csvLastMs, events: out });
  } catch (e) {
    res.status(500).json({ ok: false, error: e?.message || String(e) });
  }
});

