// ════════════════════════════════════════════════════════════════════════════
// Hedge Signals v2 — cointegration-gated pairs mean-reversion
// ────────────────────────────────────────────────────────────────────────────
// v1 (computeHedgeSignals) picks pairs for LOW correlation and trades a plain
// log(A)−log(B) spread against an all-history mean. v2 selects pairs by
// COINTEGRATION (Engle-Granger half-life + t-stat), trades the static residual
// z-scored on a rolling window, money-matches the legs (β) and adds a half-life
// time-stop. All math lives in js/hedgeSignalV2Engine.js (unit-tested, no copy).
// OANDA H4 bars are reachable in Railway, not the sandbox (403 ⇒ no_data, not a bug).

const HEDGE_SIGNAL_V2_CFG_KEY  = 'hedge_signal_v2_cfg';
const HEDGE_V2_SIGNALS_PATH    = path.join(__dirname, 'bot', 'data', 'hedge_signals_v2.json');
const HEDGE_V2_BARS_TTL        = 60 * 60 * 1000;   // reuse fetched bars for 1h
// Server-level defaults — enabled flag lives here, not in the engine (which is pure math).
const HEDGE_V2_SERVER_DEFAULTS = { ...HEDGE_V2_DEFAULTS, enabled: true };

// Candidate pairs likely to cointegrate — the gate filters which actually do.
// Equity indices co-move strongly (the colleague's DAX/SP, DOW/NAS live here),
// then metals, energy and a few FX crosses. Same OANDA symbols as CORR/BETA lists.
const HEDGE_V2_PAIRS = [
  ['NAS100_USD','SPX500_USD'], ['US30_USD','SPX500_USD'], ['US30_USD','NAS100_USD'],
  ['US2000_USD','SPX500_USD'], ['DE30_USD','SPX500_USD'], ['DE30_USD','NAS100_USD'],
  ['UK100_GBP','DE30_USD'],
  ['XAUUSD','XAGUSD'], ['XAUUSD','XPTUSD'],
  ['WTICO_USD','BCO_USD'],
  ['EURUSD','GBPUSD'], ['AUDUSD','NZDUSD'], ['USDCAD','USDCHF'],
];

let _hedgeV2Running   = false;
let _hedgeV2BarsCache = { at: 0, years: 0, closes: {} };
const hedgeV2BtJobs   = new Map();

async function _hedgeV2Bars(years = 2, force = false) {
  if (!force && _hedgeV2BarsCache.at && _hedgeV2BarsCache.years >= years
      && Date.now() - _hedgeV2BarsCache.at < HEDGE_V2_BARS_TTL) {
    return _hedgeV2BarsCache.closes;
  }
  const syms = [...new Set(HEDGE_V2_PAIRS.flat())];
  const closes = {};
  for (const sym of syms) {
    const r = await fetchH4Bars(sym, years).catch(() => null);
    if (r?.closes?.length) closes[sym] = r.closes;
  }
  _hedgeV2BarsCache = { at: Date.now(), years, closes };
  return closes;
}

async function computeHedgeSignalsV2(force = false) {
  if (_hedgeV2Running) return { status: 'busy' };
  _hedgeV2Running = true;
  try {
    if (!process.env.OANDA_KEY) return { status: 'no_data', error: 'OANDA_KEY not set' };
    // Load config first so we skip the OANDA fetch entirely when disabled.
    const cfgRaw = await kv.get(HEDGE_SIGNAL_V2_CFG_KEY).catch(() => null);
    const cfg    = cfgRaw ? { ...HEDGE_V2_SERVER_DEFAULTS, ...JSON.parse(cfgRaw) } : { ...HEDGE_V2_SERVER_DEFAULTS };
    if (!cfg.enabled && !force) return { status: 'disabled' };

    const closes = await _hedgeV2Bars(2, force);
    if (!Object.keys(closes).length)
      return { status: 'no_data', error: 'No OANDA bars (expected in sandbox; works in Railway)' };

    const now    = new Date().toISOString();
    const signals = [];
    for (const [a, b] of HEDGE_V2_PAIRS) {
      if (!closes[a] || !closes[b]) continue;
      const m = Math.min(closes[a].length, closes[b].length);
      const sig = hedgeV2Live(closes[a].slice(-m), closes[b].slice(-m), cfg);
      if (sig) signals.push({ pair_a: a, pair_b: b, ...sig, updated: now });
    }
    const out = { last_run: now, signals };
    await fs.promises.mkdir(path.dirname(HEDGE_V2_SIGNALS_PATH), { recursive: true });
    await fs.promises.writeFile(HEDGE_V2_SIGNALS_PATH, JSON.stringify(out, null, 2));
    return { status: 'ok', total: signals.length, active: signals.filter(s => s.isEntry).length };
  } catch (e) {
    console.error('[HEDGE-SIG-V2]', e.message);
    return { status: 'error', error: e.message };
  } finally {
    _hedgeV2Running = false;
  }
}

app.get('/api/hedge-signals-v2', (_req, res) => {
  if (!fs.existsSync(HEDGE_V2_SIGNALS_PATH)) return res.json({ signals: [], last_run: null });
  try { res.json(JSON.parse(fs.readFileSync(HEDGE_V2_SIGNALS_PATH, 'utf8'))); }
  catch { res.json({ signals: [], last_run: null }); }
});

app.post('/api/hedge-signals-v2/check', async (_req, res) => {
  const result = await computeHedgeSignalsV2(true).catch(e => ({ status: 'error', error: e.message }));
  res.json(result);
});

app.get('/api/hedge-signals-v2/config', async (_req, res) => {
  const raw = await kv.get(HEDGE_SIGNAL_V2_CFG_KEY).catch(() => null);
  res.json(raw ? { ...HEDGE_V2_SERVER_DEFAULTS, ...JSON.parse(raw) } : { ...HEDGE_V2_SERVER_DEFAULTS });
});

app.put('/api/hedge-signals-v2/config', express.json({ limit: '64kb' }), async (req, res) => {
  const cfg = { ...HEDGE_V2_SERVER_DEFAULTS, ...(req.body || {}) };
  await kv.put(HEDGE_SIGNAL_V2_CFG_KEY, JSON.stringify(cfg)).catch(() => {});
  res.json({ ok: true, cfg });
});

// Async IS/OOS A/B backtest: v2 (cointegration + rolling z + half-life stop) vs
// the v1-style baseline (plain spread, all-history mean, z-only exit).
app.post('/api/hedge-signals-v2/backtest/run', express.json({ limit: '64kb' }), (req, res) => {
  if (!process.env.OANDA_KEY) return res.status(400).json({ ok: false, error: 'OANDA_KEY not set' });
  const jobId     = `hsv2_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  const years     = Math.min(Math.max(parseFloat(req.body?.years) || 3, 1), 5);
  const cfg       = { ...HEDGE_V2_DEFAULTS, ...(req.body?.cfg || {}) };

  // Drop jobs older than 10 min.
  for (const [id, j] of hedgeV2BtJobs) if (Date.now() - j.startedAt > 600_000) hedgeV2BtJobs.delete(id);
  hedgeV2BtJobs.set(jobId, { status: 'running', startedAt, phase: 'Fetching OANDA H4 bars…' });

  (async () => {
    try {
      const closes = await _hedgeV2Bars(years, false);
      if (!Object.keys(closes).length) throw new Error('No OANDA bars returned (works in Railway, 403 in sandbox)');
      hedgeV2BtJobs.get(jobId).phase = 'Running cointegration + IS/OOS A/B…';
      const data = hedgeV2Comparison(closes, HEDGE_V2_PAIRS, cfg);
      hedgeV2BtJobs.set(jobId, { status: 'done', startedAt, result: { ok: true, data, runAt: new Date().toISOString() } });
      console.log(`[hedge-sig-v2-bt] job ${jobId} done (${Math.round((Date.now() - startedAt) / 1000)}s)`);
    } catch (e) {
      hedgeV2BtJobs.set(jobId, { status: 'error', startedAt, error: e?.message || String(e) });
    }
  })();

  res.json({ ok: true, jobId });
});

app.get('/api/hedge-signals-v2/backtest/status/:jobId', (req, res) => {
  const job = hedgeV2BtJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running')
    return res.json({ ok: true, status: 'running', phase: job.phase, elapsed: Math.round((Date.now() - job.startedAt) / 1000) });
  if (job.status === 'error') return res.json({ ok: false, status: 'error', error: job.error });
  res.json({ ok: true, status: 'done', ...job.result });
});

// Recompute live v2 signals on the same cadence as v1 (5 min after boot, then 15-min).
// H4 bars only change every 4 hours — hourly cadence gives the same signal without
// burning OANDA quota or CPU on 14 redundant identical runs per hour.
setTimeout(() => computeHedgeSignalsV2().catch(e => console.error('[HEDGE-SIG-V2]', e.message)), 6 * 60_000);
setInterval(() => computeHedgeSignalsV2().catch(e => console.error('[HEDGE-SIG-V2]', e.message)), 60 * 60_000);

// ── Regime log backfill (pure Node.js) ──────────────────────────────────────
// Native JS log parser — no Python subprocess required.
// Reads bot log files line-by-line with readline and writes directly to KV.

const _RG_V1_LOG = path.join(__dirname, 'bot',  'regime_bot.log');
const _RG_V2_LOG = path.join(__dirname, 'logs', 'regime_bot_v2.log');

// Regex patterns mirror parse_regime_logs.py
const _RG_PAT = {
  v1: {
    state: /^\[([^\]]+)\] \[INFO\] \[([^\]]+)\] regime=(\w+)\s+conf=(\d+)%\s+vol_z=([+-]?\d+\.?\d*)\s+rl=(\d+)\s+decay=([+-]?\d+\.?\d*)/,
    entry: /^\[([^\]]+)\] \[INFO\] \[([^\]]+)\] ENTRY (LONG|SHORT)/,
    trade: /^\[([^\]]+)\] \[INFO\] TRADE (\S+) (LONG|SHORT)\s+SL=/,
    close: /^\[([^\]]+)\] \[INFO\] CLOSE (\S+)\s+ticket=\S+\s+reason=(.+?)(?:\s+score=[\d.]+)?$/,
  },
  v2: {
    state: /^\[([^\]]+)\] \[RGV2\] \[INFO\] \[([^\]]+)\] reg=(\w+)\s+conf=(\d+)%\s+slope=([+-]?\d+\.?\d*)\s+vz=([+-]?\d+\.?\d*)\s+rl=(\d+)\s+bocpd=([+-]?\d+\.?\d*)%\s+exh=([+-]?\d+\.?\d*)\s+decay=([+-]?\d+\.?\d*)\s+score=(\d+)(?:\s+1h=(\w+))?/,
    gate:  /^\[([^\]]+)\] \[RGV2\] \[INFO\] \[([^\]]+)\] Gate: (.+)$/,
    trade: /^\[([^\]]+)\] \[RGV2\] \[INFO\] TRADE (\S+) (LONG|SHORT)\s+SL=/,
    close: /^\[([^\]]+)\] \[RGV2\] \[INFO\] CLOSE (\S+)\s+ticket=\S+\s+reason=(.+?)(?:\s+\[PAPER\])?$/,
  },
};

function _rgTs(s) { return Math.floor(new Date(s.replace(' ', 'T') + 'Z').getTime() / 1000); }

async function _parseRegimeLog(logPath, ver, recsByPair, evtsByPair, log) {
  if (!fs.existsSync(logPath)) { log(`[WARN] not found: ${logPath}`); return; }
  const P = _RG_PAT[ver];
  const rl = rlCreateInterface({ input: fs.createReadStream(logPath), crlfDelay: Infinity });
  let n = 0;
  for await (const line of rl) {
    n++;
    let m;
    if (ver === 'v1') {
      if ((m = P.state.exec(line))) {
        const [,ts,pair,regime,conf,vz,rl2,decay] = m;
        const t = _rgTs(ts);
        (recsByPair.get(pair) ?? (recsByPair.set(pair, new Map()), recsByPair.get(pair))).set(t, { ts:t, regime, conf:+conf, vz:+vz, rl:+rl2, decay:+decay });
      } else if ((m = P.entry.exec(line))) {
        const evts = evtsByPair.get(m[2]) ?? (evtsByPair.set(m[2],[]), evtsByPair.get(m[2]));
        evts.push({ ts:_rgTs(m[1]), type:'entry', pair:m[2], direction:m[3] });
      } else if ((m = P.trade.exec(line))) {
        const pair = m[2]; const evts = evtsByPair.get(pair) ?? (evtsByPair.set(pair,[]), evtsByPair.get(pair));
        evts.push({ ts:_rgTs(m[1]), type:'entry', pair, direction:m[3] });
      } else if ((m = P.close.exec(line))) {
        const pair = m[2]; const evts = evtsByPair.get(pair) ?? (evtsByPair.set(pair,[]), evtsByPair.get(pair));
        evts.push({ ts:_rgTs(m[1]), type:'close', pair, reason:m[3].trim() });
      }
    } else {
      if ((m = P.state.exec(line))) {
        const [,ts,pair,regime,conf,slope,vz,rl2,bocpd,exh,decay,score,h1] = m;
        const t = _rgTs(ts);
        (recsByPair.get(pair) ?? (recsByPair.set(pair, new Map()), recsByPair.get(pair))).set(t, { ts:t, regime, conf:+conf, slope:+slope, vz:+vz, rl:+rl2, bocpd:+bocpd, exh:+exh, decay:+decay, score:+score, h1 });
      } else if ((m = P.gate.exec(line))) {
        const pair = m[2]; const evts = evtsByPair.get(pair) ?? (evtsByPair.set(pair,[]), evtsByPair.get(pair));
        evts.push({ ts:_rgTs(m[1]), type:'gate', pair, reason:m[3] });
      } else if ((m = P.trade.exec(line))) {
        const pair = m[2].replace('_','/'); const evts = evtsByPair.get(pair) ?? (evtsByPair.set(pair,[]), evtsByPair.get(pair));
        evts.push({ ts:_rgTs(m[1]), type:'entry', pair, direction:m[3] });
      } else if ((m = P.close.exec(line))) {
        const pair = m[2].replace('_','/'); const evts = evtsByPair.get(pair) ?? (evtsByPair.set(pair,[]), evtsByPair.get(pair));
        evts.push({ ts:_rgTs(m[1]), type:'close', pair, reason:m[3].trim() });
      }
    }
  }
  log(`  ${path.basename(logPath)}: ${n.toLocaleString()} lines parsed`);
}

const _rgJobs = new Map();
function _purgeStaleRgJobs() {
  const now = Date.now();
  for (const [id, job] of _rgJobs) { if (now - job.startedAt > 30 * 60 * 1000) _rgJobs.delete(id); }
}

app.post('/api/regime-backfill-trigger', (req, res) => {
  _purgeStaleRgJobs();
  for (const job of _rgJobs.values()) {
    if (job.status === 'running') return res.json({ ok: true, jobId: job.jobId, alreadyRunning: true });
  }

  const jobId = `rg_${Date.now()}`;
  const lines = [];
  _rgJobs.set(jobId, { jobId, status: 'running', startedAt: Date.now(), lines });

  const log = msg => { lines.push(msg); if (lines.length > 400) lines.splice(0, lines.length - 400); console.log('[backfill]', msg); };

  (async () => {
    try {
      const v1r = new Map(), v1e = new Map(), v2r = new Map(), v2e = new Map();
      log('Parsing V1 log…');
      await _parseRegimeLog(_RG_V1_LOG, 'v1', v1r, v1e, log);
      log('Parsing V2 log…');
      await _parseRegimeLog(_RG_V2_LOG, 'v2', v2r, v2e, log);

      const allPairs = new Set([...v1r.keys(), ...v1e.keys(), ...v2r.keys(), ...v2e.keys()]);
      log(`Writing KV for ${allPairs.size} pairs…`);

      const pairSafe = p => p.replace('/','').replace('_','').toLowerCase();
      let written = 0;
      for (const pair of allPairs) {
        const safe = pairSafe(pair);
        for (const [ver, rMap, eMap] of [['v1', v1r, v1e], ['v2', v2r, v2e]]) {
          const records = [...(rMap.get(pair)?.values() ?? [])].sort((a,b) => a.ts - b.ts);
          const events  = (eMap.get(pair) ?? []).sort((a,b) => a.ts - b.ts);
          if (!records.length && !events.length) continue;
          await cfEnv.FX_SCORES.put(`rg${ver}_${safe}`, JSON.stringify({ records, events }));
          log(`  [OK] ${ver} ${pair}  ${records.length} records  ${events.length} events`);
          written++;
        }
      }
      log(`Done — ${written} KV keys written.`);
      const job = _rgJobs.get(jobId);
      if (job) { job.status = 'done'; job.finishedAt = Date.now(); }
    } catch (e) {
      lines.push(`[ERROR] ${e.message}`);
      console.error('[backfill]', e);
      const job = _rgJobs.get(jobId);
      if (job) { job.status = 'error'; job.finishedAt = Date.now(); }
    }
  })();

  res.json({ ok: true, jobId });
});

app.get('/api/regime-backfill-status/:jobId', (req, res) => {
  const job = _rgJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  res.json({ ok: true, status: job.status, elapsed: Math.round((Date.now() - job.startedAt) / 1000), lines: job.lines.slice(-40), exitCode: job.exitCode ?? null });
});

// ── Regime history — R2 backfill + local KV ring buffer ──────────────────────
// Must sit BEFORE the catch-all so Railway doesn't forward this to callWorker
// (callWorker reads the local file-KV which is wiped on every redeploy).
// R2 provides durable history; local KV provides data from the current run.

app.get('/api/regime-history', async (req, res) => {
  const bot    = req.query.bot === 'v1' ? 'v1' : 'v2';
  const pair   = (req.query.pair || 'eurusd').toLowerCase().replace(/[^a-z0-9]/g, '');
  const fromTs = parseInt(req.query.from || '0');
  const toTs   = parseInt(req.query.to   || '9999999999');

  const recMap = new Map();
  const evMap  = new Map();

  // 1. R2 backfill (persistent across redeploys)
  try {
    const d = await loadRegimeHistoryFromR2(bot, pair);
    if (d) {
      for (const r of (d.records || [])) recMap.set(r.ts, r);
      for (const e of (d.events  || [])) evMap.set(`${e.ts}_${e.type}`, e);
    }
  } catch {}

  // 2. Local KV ring buffer (current Railway run — last 48-96h)
  try {
    const raw = await kv.get(`rg${bot}_${pair}`);
    if (raw) {
      const d = JSON.parse(raw);
      for (const r of (d.records || [])) recMap.set(r.ts, r);
      for (const e of (d.events  || [])) evMap.set(`${e.ts}_${e.type}`, e);
    }
  } catch {}

  const records = [...recMap.values()].filter(r => r.ts >= fromTs && r.ts <= toTs).sort((a, b) => a.ts - b.ts);
  const events  = [...evMap.values()].filter(e => e.ts >= fromTs && e.ts <= toTs).sort((a, b) => a.ts - b.ts);
  res.json({ bot, pair, records, events });
});

// Export local data/regime_history JSON files to R2 (run once to seed history).
// POST /api/regime-history-export  →  { uploaded: N, results: [...] }
app.post('/api/regime-history-export', async (req, res) => {
  const histDir = path.join(__dirname, 'data', 'regime_history');
  if (!fs.existsSync(histDir)) return res.json({ ok: false, error: 'data/regime_history not found — this endpoint must be called against your LOCAL server (localhost:3000), not Railway. Railway does not have these gitignored files.' });
  const results = [];
  for (const bot of ['v1', 'v2']) {
    const botDir = path.join(histDir, bot);
    if (!fs.existsSync(botDir)) continue;
    for (const file of fs.readdirSync(botDir).filter(f => f.endsWith('.json'))) {
      const pair    = file.replace('.json', '');
      const content = fs.readFileSync(path.join(botDir, file), 'utf8');
      try {
        const data = JSON.parse(content);
        await saveRegimeHistoryToR2(bot, pair, data);
        results.push({ ok: true, bot, pair, bytes: content.length });
      } catch (e) {
        results.push({ ok: false, bot, pair, error: e.message });
      }
    }
  }
  res.json({ ok: true, uploaded: results.filter(r => r.ok).length, results });
});

// ── Pivot Spike Backtest ─────────────────────────────────────────────────────

const psJobs = new Map();

function _purgeStalePsJobs() {
  const cutoff = Date.now() - 60 * 60_000;
  for (const [id, job] of psJobs) if (job.startedAt < cutoff) psJobs.delete(id);
}

app.post('/api/pivot-spike/run', express.json({ limit: '64kb' }), (req, res) => {
  const b   = req.body ?? {};
  const num = (v, d) => (v === undefined || v === '' || isNaN(+v) ? d : +v);
  const opts = {
    pair:        typeof b.pair === 'string' ? b.pair.toLowerCase().replace('/', '') : 'eurusd',
    touchTolAtr: num(b.touchTolAtr, 0.5),
    slAtr:       num(b.slAtr,       1.0),
    maxBars:     Math.round(num(b.maxBars, 120)),
    oosFrac:     Math.min(Math.max(num(b.oosFrac, 0.35), 0.1), 0.6),
    costPct:     num(b.costPct, 0.0002),
  };
  const jobId     = `ps_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const startedAt = Date.now();
  _purgeStalePsJobs();
  psJobs.set(jobId, { status: 'running', startedAt, log: [] });
  (async () => {
    const log = [];
    const onLog = msg => { log.push(msg); console.log(`[pivot-spike] ${msg}`); };
    try {
      const result = await runPivotSpike(opts, onLog);
      psJobs.set(jobId, { status: 'done', result: { ...result, log }, startedAt });
    } catch (e) {
      const msg = e?.message || String(e) || 'Unknown error';
      console.error('[pivot-spike/run]', msg, e?.stack ?? '');
      psJobs.set(jobId, { status: 'error', error: msg, log, startedAt });
    }
  })();
  res.json({ ok: true, jobId });
});

app.get('/api/pivot-spike/status/:jobId', (req, res) => {
  const job = psJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running') {
    return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - job.startedAt) / 1000), log: job.log });
  }
  if (job.status === 'done') return res.json({ ok: true, status: 'done', ...job.result });
  return res.status(500).json({ ok: false, status: 'error', error: job.error, log: job.log });
});

// ─────────────────────────────────────────────────────────────────────────────
// Trade Decision Engine — per-event go/skip scoring API (fast loop).
// Slow loop: snapshots warm ON DEMAND inside decide (a bot only ever needs
// pair + price); TDE_PAIRS keeps them pre-warmed so calls stay in the ms range.
// Registered BEFORE the /api/* catch-all so the worker proxy doesn't swallow it.
// Full design: Trade_Decision_Engine/ARCHITECTURE.md. UI: trade-decision-engine.html.

// Synthetic snapshots are cached so repeated harness calls stay in the ms range.
const _tdeSynthCache = new Map();
function tdeSnapshotFor(pair, mode) {
  if (mode === 'synthetic') {
    let s = _tdeSynthCache.get(pair);
    if (!s || Date.now() - s.builtAt > 10 * 60_000) {
      s = tdeSyntheticSnapshot(pair, { newsInMin: 180 });
      _tdeSynthCache.set(pair, s);
    }
    return s;
  }
  return tdeGetState(pair);
}

// On-demand slow loop: decide() warms its own snapshot when missing or stale.
// First call per pair pays the OANDA fetch (~1–2 s); subsequent calls hit the
// in-memory snapshot in ms. Per-pair in-flight dedup so simultaneous zone
// touches don't double-fetch. Never rejects: a failed warm-up falls back to
// whatever snapshot exists (decide then fails closed on staleness) and the
// error is surfaced as `slow_loop_error` so the caller knows WHY.
const TDE_WARM_STALE_MS = 15 * 60_000;   // matches decisionCore DECIDE_DEFAULTS.maxStalenessMs
const _tdeWarmInflight = new Map();
function tdeWarmSnapshot(pair) {
  const cur = tdeGetState(pair);
  if (cur && Date.now() - cur.builtAt <= TDE_WARM_STALE_MS) {
    return Promise.resolve({ snap: cur, refreshed: false });
  }
  let inflight = _tdeWarmInflight.get(pair);
  if (!inflight) {
    inflight = (async () => {
      try { return { snap: await tdeRefreshPair(pair, { macro: await _tdeMacroFor(pair), credit: await _tdeCreditContext() }), refreshed: true }; }
      catch (e) { return { snap: tdeGetState(pair), refreshed: false, error: e.message ?? String(e) }; }
      finally { _tdeWarmInflight.delete(pair); }
    })();
    _tdeWarmInflight.set(pair, inflight);
  }
  return inflight;
}

// The bot-facing endpoint — pair + price is enough, the engine sorts the rest:
// { pair, price?, action?, direction?, approach_sigma?, own_level?, intraday?, mode? }
// intraday (optional bot override): { rangeUsed, posInRange, vwapDistSigma,
// approachSigma } — fresher than the snapshot's slow-loop block if you have it.
app.post('/api/trade-decision/decide', express.json(), async (req, res) => {
  const t0 = Date.now();
  try {
    const { pair, price, action, direction, approach_sigma, own_level, intraday, mode = 'live' } = req.body ?? {};
    if (!pair) return res.status(400).json({ ok: false, error: 'pair required' });
    const key = String(pair).toLowerCase();
    let snap, warm = null;
    if (mode === 'synthetic') snap = tdeSnapshotFor(key, 'synthetic');
    else { warm = await tdeWarmSnapshot(key); snap = warm.snap; }
    const result = tdeDecide(snap, {
      pair, price: price != null ? Number(price) : undefined,
      action, direction, approachSigma: approach_sigma, own_level: own_level === true,
      intraday: intraday && typeof intraday === 'object' ? intraday : undefined,
    });
    if (warm) {
      result.snapshot_refreshed = warm.refreshed;
      if (warm.error) result.slow_loop_error = warm.error;
    }
    result.total_ms = Date.now() - t0;
    tdeAppendDecision({ request: { pair, price, action, direction, approach_sigma, own_level, mode }, result });
    res.json(result);
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message ?? String(e) });
  }
});

// Shadow scoring — run every open bot position through the model, read-only.
// The Positions tab (all bots aggregated) POSTs its live positions; the engine
// scores each at its OPEN price + direction and returns a suggestion keyed by
// ticket. This NEVER touches the bots — it is advisory ("would the model take /
// keep this?"), the shadow layer the honest-teammate plan calls for. One call
// per tab refresh: each pair's snapshot is warmed once, then reused.
//
// own_level:true — the trade IS the caller's own level, so a touch with no
// mapped zone scores as a standalone external level (confluence 1) instead of a
// no_level_nearby skip (ARCHITECTURE.md §3 gate 4). Every position gets a score.
//
// Honesty: v0 is a hand-weighted PRIOR (calibrated:false), and the snapshot is
// built NOW, not at the trade's entry — so this is a "live read", not entry-time
// truth. It becomes evidence only once a fit trained on these shadow rows beats
// the prior on OOS calibration. Each ticket is shadow-logged ONCE (in-memory
// dedupe; resets on redeploy — acceptable for a shadow log) so the real bot
// trades start accumulating the labeled set a fit needs.
const _tdePosShadowSeen = new Set(); // ticket → already shadow-logged this process
app.post('/api/trade-decision/score-positions', express.json({ limit: '2mb' }), async (req, res) => {
  try {
    const positions = Array.isArray(req.body?.positions) ? req.body.positions : [];
    if (!positions.length) return res.json({ ok: true, suggestions: {}, model_version: TDE_MODEL.version, calibrated: TDE_MODEL.calibrated });

    // Resolve symbols → canonical keys, warm each distinct snapshot once.
    const wantPairs = new Set();
    for (const p of positions) { const k = resolveKey(p.symbol); if (k) wantPairs.add(k); }
    const warmed = {};
    await Promise.all([...wantPairs].map(async k => {
      try { warmed[k] = (await tdeWarmSnapshot(k)).snap; }
      catch { warmed[k] = tdeGetState(k); }
    }));

    const suggestions = {};
    const shadowRecords = [];
    for (const p of positions) {
      const ticket = p.ticket;
      if (ticket == null) continue;
      const key = resolveKey(p.symbol);
      if (!key) { suggestions[ticket] = { decision: 'n/a', reason: 'unmapped symbol' }; continue; }
      const snap = warmed[key];
      if (!snap) { suggestions[ticket] = { decision: 'n/a', reason: 'no snapshot (OANDA unreachable?)' }; continue; }
      const direction = p.direction === 'BUY' ? 'long' : p.direction === 'SELL' ? 'short' : undefined;
      try {
        const r = tdeDecide(snap, {
          pair: key,
          price: p.open_price != null ? Number(p.open_price) : undefined,
          direction, own_level: true,
        });
        suggestions[ticket] = {
          decision: r.decision, probability: r.probability, size_multiplier: r.size_multiplier,
          top_factor: (r.top_factors && r.top_factors[0]) || null,
          reason: (r.reasons && r.reasons[0]) || null,
          calibrated: r.calibrated, model_version: r.model_version,
        };
        // Durable book, keyed by position_id, for the Trade History outcome join.
        shadowRecords.push({ id: ticket, entry: _tdeShadowEntry(r, p, p.bot, key) });
        if (!_tdePosShadowSeen.has(ticket)) {
          _tdePosShadowSeen.add(ticket);
          tdeAppendDecision({
            source: 'position-shadow', bot: p.bot || null, ticket, symbol: p.symbol,
            request: { pair: key, price: p.open_price, direction, own_level: true }, result: r,
          });
        }
      } catch (e) {
        suggestions[ticket] = { decision: 'error', reason: e.message ?? String(e) };
      }
    }
    _tdeShadowRecord(shadowRecords);   // fire-and-forget durable capture (≈entry reading kept)
    res.json({ ok: true, suggestions, model_version: TDE_MODEL.version, calibrated: TDE_MODEL.calibrated });
  } catch (e) {
    res.status(500).json({ ok: false, error: e.message ?? String(e) });
  }
});

// ── Durable TDE shadow book ──────────────────────────────────────────────────
// What the model said about each OPEN trade, keyed by position_id, persisted to
// KV (tde_shadow_*) so the Trade History audit can join it to the realized
// outcome. decisions.jsonl is ephemeral (redeploy-wiped) and never joined; this
// is the durable, outcome-joinable record. Single writer via a promise-chain
// mutex so the UI endpoint and the background loop never clobber each other.
// Honesty: v0 is an uncalibrated prior over a signal shown to be null — do NOT
// expect GO-tagged trades to beat SKIP-tagged ones on it. The point is to build
// the labeled set on the bots' REAL entries, the one thing not yet tested.
const _TDE_SHADOW_KV = 'tde_shadow_book';
const _TDE_SHADOW_MAX = 6000;
const _tdeShadowSeen = new Set();      // position_id already booked (fast path)
let _tdeShadowWrite = Promise.resolve();

async function _tdeShadowBookGet() {
  try { const raw = await kv.get(_TDE_SHADOW_KV); return raw ? (JSON.parse(raw).data ?? JSON.parse(raw)) : {}; }
  catch { return {}; }
}
// Map a decide() result + position into a compact shadow entry.
function _tdeShadowEntry(r, pos, botKey, key) {
  return {
    decision: r.decision, probability: r.probability, size_multiplier: r.size_multiplier,
    direction: r.direction ?? (pos.direction === 'BUY' ? 'long' : pos.direction === 'SELL' ? 'short' : null),
    top_factor: (r.top_factors && r.top_factors[0]) || null,
    model_version: r.model_version, calibrated: r.calibrated,
    bot: botKey || null, symbol: pos.symbol, pair: key, trade_dir: pos.direction, at: Date.now(),
  };
}
// records: [{ id, entry }]; only ids not already booked are added (earliest kept ≈ entry). Serialized.
function _tdeShadowRecord(records) {
  const fresh = (records || []).filter(r => r && r.id != null && !_tdeShadowSeen.has(String(r.id)));
  if (!fresh.length) return _tdeShadowWrite;
  _tdeShadowWrite = _tdeShadowWrite.then(async () => {
    const book = await _tdeShadowBookGet();
    let added = 0;
    for (const { id, entry } of fresh) {
      const k = String(id);
      _tdeShadowSeen.add(k);
      if (book[k]) continue;                    // keep the EARLIEST reading (≈ entry)
      book[k] = entry; added++;
    }
    if (!added) return;
    const ids = Object.keys(book);
    if (ids.length > _TDE_SHADOW_MAX) {
      ids.sort((a, b) => (book[a].at ?? 0) - (book[b].at ?? 0));
      for (const id of ids.slice(0, ids.length - _TDE_SHADOW_MAX)) delete book[id];
    }
    try { await kv.put(_TDE_SHADOW_KV, JSON.stringify({ data: book, timestamp: Date.now() })); }
    catch (e) { console.warn('[tde-shadow] put failed:', e.message); }
  }).catch(e => console.error('[tde-shadow] record failed:', e.message));
  return _tdeShadowWrite;
}

// Background accumulator — score every OPEN position across the bots and book the
// reading once, independent of anyone viewing the Positions tab. Mirrors
// _rlAccumulateTradeLog's cadence. Railway only (snapshots need OANDA).
const _TDE_SHADOW_STATUS_KEYS = ['bot_status', 'regime_bot_status', 'gold_bot_status', 'gold_v2_status', 'confluence_bot_status', 'regime_bot_v2_status', 'regime_bot_v7_status', 'dyn_anchor_status', 'macro_equity_bot_status', 'volatility_bot_status', 'volatility_ride_status', 'range_line_bot_status', 'oi_bot_status'];
async function _tdeAccumulateShadowBook() {
  try {
    const open = [];
    for (const sk of _TDE_SHADOW_STATUS_KEYS) {
      const raw = await kv.get(sk).catch(() => null);
      if (!raw) continue;
      let status; try { status = JSON.parse(raw).data ?? JSON.parse(raw); } catch { continue; }
      for (const p of (status?.mt5_positions || [])) {
        const id = p.ticket ?? p.position_id;
        if (id == null || _tdeShadowSeen.has(String(id))) continue;
        open.push({ id, pos: p, bot: sk });
      }
    }
    if (!open.length) return;
    const wanted = new Set(open.map(o => resolveKey(o.pos.symbol)).filter(Boolean));
    const snaps = {};
    for (const k of wanted) { try { snaps[k] = (await tdeWarmSnapshot(k)).snap; } catch { snaps[k] = tdeGetState(k); } }
    const records = [];
    for (const { id, pos, bot } of open) {
      const key = resolveKey(pos.symbol); const snap = key && snaps[key];
      if (!snap) continue;
      try {
        const direction = pos.direction === 'BUY' ? 'long' : pos.direction === 'SELL' ? 'short' : undefined;
        const r = tdeDecide(snap, { pair: key, price: pos.open_price != null ? Number(pos.open_price) : undefined, direction, own_level: true });
        records.push({ id, entry: _tdeShadowEntry(r, pos, bot, key) });
      } catch {}
    }
    if (records.length) { await _tdeShadowRecord(records); console.log(`[tde-shadow] booked ${records.length} open position(s)`); }
  } catch (e) { console.error('[tde-shadow] accumulate failed:', e.message); }
}
if (process.env.OANDA_KEY) {
  setInterval(_tdeAccumulateShadowBook, 7 * 60_000);
  setTimeout(_tdeAccumulateShadowBook, 45_000);
}

// Read the shadow book (optionally a subset by ?ids=a,b,c) — the audit joins it.
app.get('/api/trade-decision/shadow-book', async (req, res) => {
  try {
    const book = await _tdeShadowBookGet();
    const ids = req.query.ids ? String(req.query.ids).split(',').map(s => s.trim()).filter(Boolean) : null;
    const out = ids ? Object.fromEntries(ids.filter(id => book[id]).map(id => [id, book[id]])) : book;
    res.json({ ok: true, book: out, total: Object.keys(book).length });
  } catch (e) { res.status(500).json({ ok: false, error: e.message ?? String(e) }); }
});

// Snapshot inspection (staleness, regime, zones) — ?mode=synthetic for the demo path
app.get('/api/trade-decision/state/:pair', (req, res) => {
  try {
    const snap = tdeSnapshotFor(String(req.params.pair).toLowerCase(), req.query.mode ?? 'live');
    if (!snap) return res.json({ ok: false, error: 'no snapshot yet — decide warms one automatically on first call; or POST /api/trade-decision/refresh, or use mode=synthetic' });
    const { zones, calendar, ...head } = snap;
    res.json({ ok: true, ...head, age_ms: Date.now() - snap.builtAt, zones: zones.slice(0, 40), calendar_events: calendar.length });
  } catch (e) { res.status(500).json({ ok: false, error: e.message ?? String(e) }); }
});

// Live macro context for the TDE (ARCHITECTURE §7c #1): resolve the obs-dated
// FRED history already cached by refreshFredHistory (fredhistory_series_vix /
// _hy — 90 obs each, plenty for the 20-obs HY window) through macroCore, and
// hand refreshPair the pre-resolved { regime, riskSens, asOf, stale } object.
// FAIL-NEUTRAL: any miss (KV empty, FRED down, driverless pair) yields a null
// or stale-NEUTRAL context — macro is a modifier, never a gate.
let _tdeMacroHist = null, _tdeMacroHistAt = 0;
async function _tdeMacroHistory() {
  if (_tdeMacroHist && Date.now() - _tdeMacroHistAt < 10 * 60_000) return _tdeMacroHist;
  try {
    const [vixRaw, hyRaw] = await Promise.all([
      kv.get('fredhistory_series_vix'), kv.get('fredhistory_series_hy'),
    ]);
    const parse = raw => { const d = typeof raw === 'string' ? JSON.parse(raw) : raw; return Array.isArray(d) ? d : (d?.data ?? null); };
    const vix = parse(vixRaw), hy = parse(hyRaw);
    _tdeMacroHist = vix?.length && hy?.length ? { vix, hy } : null;
  } catch (e) {
    console.warn('[trade-decision] macro history read failed (fail-neutral):', e.message ?? e);
    _tdeMacroHist = null;
  }
  _tdeMacroHistAt = Date.now();
  return _tdeMacroHist;
}
async function _tdeMacroFor(pair) {
  const hist = await _tdeMacroHistory();
  if (!hist) return null;                       // no data → snapshot stamps null (neutral)
  try { return _macroContext(pair, hist, Date.now()); } catch { return null; }
}

// Credit context for the TDE snapshot (market-wide HY-OAS gate; pair-INDEPENDENT,
// so resolved ONCE and cached — the HMM EM is the only pricey bit). Reuses the HY
// history the macro loop already loaded. LOGGED-BUT-INERT: it stamps
// snapshot.credit → the credit_* candidate features, which carry NO v0 weight, so
// live decisions are unchanged until a promoted fit earns them (§7c). Fail-neutral.
let _tdeCreditCtx = null, _tdeCreditCtxAt = 0;
async function _tdeCreditContext() {
  if (_tdeCreditCtx !== null && Date.now() - _tdeCreditCtxAt < 10 * 60_000) return _tdeCreditCtx;
  _tdeCreditCtxAt = Date.now();
  try {
    const hist = await _tdeMacroHistory();
    const hy = (hist?.hy ?? []).map(o => o.value).filter(Number.isFinite);   // oldest→newest
    if (hy.length < 30) { _tdeCreditCtx = null; return null; }
    const g = _creditGateBrick(hy);                                          // gate + features
    const reg = hy.length >= 60 ? _creditRegime(hy) : null;                  // HMM persistence
    _tdeCreditCtx = g ? {
      gate: g.gate, widening: g.widening, wideningBps: g.d5 ?? g.d1 ?? null, pct: g.pct ?? null,
      accel: g.accel ?? 0, stressProb: reg?.curStressProb ?? null,
      asOf: hist?.hy?.[hist.hy.length - 1]?.date ?? null, stale: false,
    } : null;
  } catch (e) {
    console.warn('[trade-decision] credit context failed (fail-neutral):', e.message ?? e);
    _tdeCreditCtx = null;
  }
  return _tdeCreditCtx;
}

// ── Telegram alert when the credit gate flips regime ─────────────────────────
// Credit is the market's early-warning system; a flip (e.g. RISK-ON → CAUTION →
// RISK-OFF, or back) is a "re-check your risk" event worth one push. Server-side,
// gated by the same state.tg / state.cfg as the other alerts; cooldown 1h.
let _lastCreditGate = null, _lastCreditAlertAt = 0;
const CREDIT_ALERT_COOLDOWN_MS = 60 * 60_000;
async function _creditFlipCheck() {
  try {
    const ctx = await _tdeCreditContext();
    if (!ctx?.gate) return;
    const prev = _lastCreditGate;
    _lastCreditGate = ctx.gate;
    if (!prev || prev === ctx.gate) return;                       // first read or no change
    if (state.cfg?.enabled === false || !state.tg?.token || !state.tg?.chatId) return;
    if (Date.now() - _lastCreditAlertAt < CREDIT_ALERT_COOLDOWN_MS) return;
    const worse = ['RISK-ON', 'NEUTRAL', 'CAUTION', 'RISK-OFF'].indexOf(ctx.gate) > ['RISK-ON', 'NEUTRAL', 'CAUTION', 'RISK-OFF'].indexOf(prev);
    const so = ctx.widening > 0
      ? 'Spreads widening — credit stress can lead equity vol / risk-off. Headwind for NAS100/SPX; watch risk FX.'
      : ctx.widening < 0 ? 'Spreads tightening — improving risk appetite, supportive for stocks.' : 'Credit direction has shifted.';
    const msg = [
      `${worse ? '🚨' : '🟢'} <b>Credit regime change</b>`,
      `${prev} → <b>${ctx.gate}</b>`,
      `HY OAS <b>${ctx.wideningBps != null ? (ctx.wideningBps >= 0 ? '+' : '') + ctx.wideningBps + 'bps/wk' : '—'}</b>${ctx.pct != null ? ` · P${ctx.pct}` : ''}${ctx.stressProb != null ? ` · stress ${(100 * ctx.stressProb).toFixed(0)}%` : ''}`,
      so,
      `<i>${new Date().toISOString().replace('T', ' ').substring(0, 16)} UTC · not yet OOS-validated</i>`,
    ].join('\n');
    const sent = await sendTelegram(state.tg.token, state.tg.chatId, msg);
    if (sent) _lastCreditAlertAt = Date.now();
  } catch (e) { console.warn('[credit-alert] check failed:', e.message ?? e); }
}
if (process.env.FRED_KEY) {
  setTimeout(() => { _creditFlipCheck(); setInterval(_creditFlipCheck, 30 * 60_000); }, 90_000);
}

// Slow-loop refresh (OANDA + Finnhub) — { pair } or { pairs: [...] }
app.post('/api/trade-decision/refresh', express.json(), async (req, res) => {
  const pairs = req.body?.pairs ?? (req.body?.pair ? [req.body.pair] : TDE_DEFAULT_PAIRS);
  const out = {};
  for (const p of pairs) {
    try {
      const s = await tdeRefreshPair(p, { macro: await _tdeMacroFor(p), credit: await _tdeCreditContext() });
      out[p] = { ok: true, builtAt: s.builtAt, zones: s.zones.length, regime: s.regime,
                 macro: s.macro ? { regime: s.macro.regime, stale: s.macro.stale } : null };
    }
    catch (e) { out[p] = { ok: false, error: e.message ?? String(e) }; }
  }
  res.json({ ok: Object.values(out).some(r => r.ok), pairs: out });
});

app.get('/api/trade-decision/log', (req, res) => {
  res.json({ ok: true, decisions: tdeReadRecent(Math.min(parseInt(req.query.limit ?? '50'), 500)) });
});

app.get('/api/trade-decision/health', (_req, res) => {
  res.json({ ok: true, model_version: TDE_MODEL.version, calibrated: TDE_MODEL.calibrated,
    weights: TDE_MODEL.weights, intercept: TDE_MODEL.intercept, snapshots: tdeStateSummary() });
});

// Opt-in auto refresher: TDE_PAIRS=eurusd,gbpusd (+ TDE_REFRESH_MIN, default 5).
// Runs the slow loop HERE (not featureState.startRefresher) so every snapshot
// carries the live macro context via the refreshPair({ macro }) socket —
// featureState stays untouched, per the §7c frozen-contract split.
if (process.env.TDE_PAIRS) {
  const tdePairs = process.env.TDE_PAIRS.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  const tdeMin = parseFloat(process.env.TDE_REFRESH_MIN || '5');
  let _tdeLoopBusy = false;
  const _tdeTick = async () => {
    if (_tdeLoopBusy) return;
    _tdeLoopBusy = true;
    for (const p of tdePairs) {
      try { await tdeRefreshPair(p, { macro: await _tdeMacroFor(p), credit: await _tdeCreditContext() }); }
      catch (e) { console.log(`[trade-decision] refresh ${p} failed: ${e.message ?? e}`); }
    }
    _tdeLoopBusy = false;
  };
  setTimeout(() => {
    _tdeTick();
    setInterval(_tdeTick, tdeMin * 60_000);
    console.log(`[trade-decision] macro-aware slow loop started: ${tdePairs.join(', ')} every ${Math.round(tdeMin * 60)}s`);
  }, 5_000);
}

// Backfill: replay M1 parquet history through the SAME decide() path → labeled
// event log + candidate-model fit with OOS calibration report. Incremental by
// default (only new days). Async-job pattern like the other backtest routes.
// Full obs-dated FRED history for the backfill's macro injection (VIXCLS +
// BAMLH0A0HYM2, ~12y — the two PRE-REGISTERED factors, nothing else). Cached
// in KV for 24h; any failure returns null and the backfill runs macro-neutral
// with a loud log (fail-neutral, §7c #6 — never block the replay on FRED).
const _MACRO_HIST_KV = 'macro_fred_history_v1';
async function _loadMacroFredHistoryFull(onLog = () => {}) {
  try {
    const cached = await kv.get(_MACRO_HIST_KV);
    if (cached) {
      const d = typeof cached === 'string' ? JSON.parse(cached) : cached;
      if (d?.vix?.length && d?.hy?.length && Date.now() - (d.fetchedAt ?? 0) < 24 * 3600_000) return d;
    }
  } catch {}
  if (!process.env.FRED_KEY) { onLog('macro: FRED_KEY not set — backfill runs macro-neutral'); return null; }
  const out = { fetchedAt: Date.now() };
  for (const [key, id] of Object.entries(_MACRO_FRED_SERIES)) {
    const url = `https://api.stlouisfed.org/fred/series/observations?series_id=${id}` +
      `&api_key=${process.env.FRED_KEY}&file_type=json&observation_start=2012-01-01`;
    const r = await fetch(url, { signal: AbortSignal.timeout(30_000) });
    if (!r.ok) throw new Error(`FRED ${id} HTTP ${r.status}`);
    const d = await r.json();
    out[key] = (d.observations || [])
      .filter(o => o.value && o.value !== '.')
      .map(o => ({ date: o.date, value: parseFloat(o.value) }));
    if (!out[key].length) throw new Error(`FRED ${id}: no observations`);
  }
  await kv.put(_MACRO_HIST_KV, JSON.stringify(out)).catch(e => console.warn('[tde-backfill] macro history cache write failed:', e.message));
  onLog(`macro: FRED history loaded (${out.vix.length} VIX obs, ${out.hy.length} HY obs)`);
  return out;
}

const tdeBackfillJobs = new Map();
let tdeBackfillRunning = false;
function tdeStartBackfillJob(pairs, { incremental, gapFill = true, macro = true }) {
  const jobId = `tdebf_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const job = { status: 'running', startedAt: Date.now(), log: [] };
  tdeBackfillJobs.set(jobId, job);
  tdeBackfillRunning = true;
  (async () => {
    const onLog = m => { job.log.push(m); console.log(`[tde-backfill] ${m}`); };
    try {
      // riskSens is PAIR-specific, so the §7c contextByDate socket is fed per
      // pair: one runBackfill call per pair with that pair's own macro map.
      let fredHist = null;
      if (macro) {
        try { fredHist = await _loadMacroFredHistoryFull(onLog); }
        catch (e) { onLog(`macro: FRED history load FAILED (${e.message ?? e}) — running macro-neutral`); }
      } else onLog('macro: disabled for this run (baseline/incumbent mode)');

      // For the MACRO test, drop pairs with no riskSens driver (gold + the index
      // CFDs). Their macro_align is always 0, so they add nothing to the bucket /
      // ablation — they only dilute the neutral control, and the index M1
      // parquets (dax/dow) are the ones that fail to load. Baseline runs keep the
      // full list (the incumbent report is over everything).
      let runPairs = pairs;
      if (macro && fredHist) {
        runPairs = pairs.filter(p => _riskSensFor(p) != null);
        const skipped = pairs.filter(p => _riskSensFor(p) == null);
        if (skipped.length) onLog(`macro: skipping ${skipped.length} driverless pair(s) — ${skipped.join(', ')} (macro_align≡0, nothing to test)`);
      }

      // CRITICAL: a full rebuild (!incremental) must wipe the event log + state
      // exactly ONCE, up front — NOT per pair. runBackfill's own `!incremental`
      // unlink fires on every call, so looping it per pair would leave only the
      // LAST pair's events (the bug that killed the macro rebuild: dax is last,
      // has no data, and wiped everything before it). Reset once, then run each
      // pair incrementally so events ACCUMULATE. Nightly incremental top-ups are
      // untouched (they never reset).
      if (!incremental) { tdeResetBackfillStore(); onLog('full rebuild — event log + state reset once (pairs accumulate)'); }

      let report = null;
      for (const pair of runPairs) {
        const contextByDate = fredHist ? _macroContextByDate(pair, fredHist) : null;
        if (fredHist) onLog(`${pair}: macro context ${contextByDate && Object.keys(contextByDate).length ? `${Object.keys(contextByDate).length} days` : 'none (no riskSens driver) — macro-neutral'}`);
        report = await tdeRunBackfill([pair], { incremental: true, gapFill, contextByDate, onLog });
      }
      job.status = 'done'; job.report = report;
    } catch (e) {
      job.status = 'error'; job.error = e.message ?? String(e);
      console.error('[tde-backfill]', e);
    } finally { tdeBackfillRunning = false; }
  })();
  return jobId;
}

app.post('/api/trade-decision/backfill/run', express.json(), async (req, res) => {
  if (tdeBackfillRunning) return res.status(409).json({ ok: false, error: 'a backfill is already running' });
  const pairs = (req.body?.pairs?.length ? req.body.pairs : TDE_BACKFILL_PAIRS).map(p => String(p).toLowerCase());
  const incremental = req.body?.full !== true;
  const gapFill = typeof req.body?.gap_fill === 'boolean' ? req.body.gap_fill : (await tdeGetConfig()).gap_fill;
  const macro = req.body?.macro !== false;   // { macro: false } = incumbent-baseline mode (§7c sequencing)
  res.json({ ok: true, jobId: tdeStartBackfillJob(pairs, { incremental, gapFill, macro }), pairs: pairs.length, incremental, gap_fill: gapFill, macro });
});

app.get('/api/trade-decision/backfill/status/:jobId', (req, res) => {
  const job = tdeBackfillJobs.get(req.params.jobId);
  if (!job) return res.status(404).json({ ok: false, error: 'Job not found or expired' });
  if (job.status === 'running') return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - job.startedAt) / 1000), log: job.log });
  if (job.status === 'done') return res.json({ ok: true, status: 'done', report: job.report, log: job.log });
  return res.status(500).json({ ok: false, status: 'error', error: job.error, log: job.log });
});

app.get('/api/trade-decision/backfill/report', (_req, res) => {
  const report = tdeReadBackfillReport();
  if (!report) return res.json({ ok: false, error: 'no backfill yet — POST /api/trade-decision/backfill/run' });
  res.json({ ok: true, report });
});

// ── Macro verdict (#7) — the two frozen falsification tests over the event log.
// PRIMARY: macroBucketReport vs the frozen MACRO_BUCKET_BAR (OPPOSED must
// underperform NEUTRAL with n≥30, ≥8 episodes, ≥3 years, sign-stable per year).
// SECONDARY: ablation — fitLogistic with vs without macro_align, embargo 30d;
// on primary-pass/ablation-fail disagreement, the L2-exempt re-run is applied
// automatically (§7c #5: shrinkage on a rare feature biases toward "fails").
// The endpoint REPORTS; promotion stays a human decision on this evidence.
function tdeComputeMacroVerdict() {
  const events = tdeReadEvents();
  const bucket = tdeMacroBucketReport(events);
  const macroEvents = (bucket.aligned?.n ?? 0) + (bucket.opposed?.n ?? 0);
  if (!events.length) return { ok: false, error: 'no events — run a backfill first' };
  if (!macroEvents) return {
    ok: true, verdict: 'NO_MACRO_DATA', events: events.length, bucket,
    note: 'every event is macro-neutral — run the macro-ON full rebuild (step 2) first',
  };

  // PRIMARY — bucket test against the frozen bar
  const opp = bucket.opposed, neu = bucket.neutral;
  const oppUnderperforms = opp.n > 0 && neu.n > 0 ? opp.avgPnlPct < neu.avgPnlPct : null;
  let checkedYears = 0, stableYears = 0;
  for (const [y, s] of Object.entries(opp.perYear ?? {})) {
    const ny = neu.perYear?.[y];
    if (s.n >= 5 && ny && ny.n >= 5) { checkedYears++; if (s.avgPnlPct < ny.avgPnlPct) stableYears++; }
  }
  const signStable = checkedYears >= bucket.bar.minYears && stableYears === checkedYears;
  const primaryPass = opp.meetsBar === true && oppUnderperforms === true && signStable;

  // SECONDARY — ablation on identical splits (macro runs use embargo 30d)
  const baseFeatures = Object.keys(TDE_MODEL.weights).filter(k => k !== 'macro_align');
  const withMacro = [...new Set([...baseFeatures, 'macro_align'])];
  const fitBase  = tdeFitLogistic(events, { features: baseFeatures, embargoDays: 30 });
  const fitMacro = tdeFitLogistic(events, { features: withMacro,  embargoDays: 30 });
  const brier = f => (f?.ok ? f.oos?.fitted?.brier ?? null : null);
  let secondaryPass = brier(fitBase) != null && brier(fitMacro) != null ? brier(fitMacro) < brier(fitBase) : null;
  let fitMacroL2Exempt = null, l2ExemptApplied = false;
  if (primaryPass && secondaryPass === false) {
    fitMacroL2Exempt = tdeFitLogistic(events, { features: withMacro, embargoDays: 30, l2ExemptFeatures: ['macro_align'] });
    if (brier(fitMacroL2Exempt) != null && brier(fitMacroL2Exempt) < brier(fitBase)) { secondaryPass = true; l2ExemptApplied = true; }
  }

  const verdict = primaryPass && secondaryPass ? 'PASS'
    : primaryPass ? 'PASS_PRIMARY_ONLY'   // bucket evidence real, ablation shy — human call
    : 'FAIL';
  return {
    ok: true, verdict, generatedAt: Date.now(), events: events.length,
    primary: { pass: primaryPass, oppUnderperforms, signStable,
               stableYears, checkedYears, bucket },
    secondary: { pass: secondaryPass, l2ExemptApplied,
                 brier: { baseline: brier(fitBase), withMacro: brier(fitMacro), withMacroL2Exempt: brier(fitMacroL2Exempt) },
                 macroWeight: fitMacro?.ok ? fitMacro.candidate?.weights?.macro_align ?? null : null,
                 baseline: fitBase, withMacro: fitMacro, withMacroL2Exempt: fitMacroL2Exempt },
    note: 'Promotion to modelV1 is a MANUAL decision on this evidence (TDE §7c). '
        + 'Both tests failing means macro stays out of the feature vector permanently.',
  };
}

let _tdeVerdictJob = null;   // { status, startedAt, result?, error? } — one at a time
app.post('/api/trade-decision/macro-verdict/run', (_req, res) => {
  if (_tdeVerdictJob?.status === 'running') return res.status(409).json({ ok: false, error: 'verdict already computing' });
  _tdeVerdictJob = { status: 'running', startedAt: Date.now() };
  setImmediate(() => {
    try { _tdeVerdictJob = { status: 'done', startedAt: _tdeVerdictJob.startedAt, result: tdeComputeMacroVerdict() }; }
    catch (e) { _tdeVerdictJob = { status: 'error', error: e.message ?? String(e) }; console.error('[tde-verdict]', e); }
  });
  res.json({ ok: true, status: 'running' });
});
app.get('/api/trade-decision/macro-verdict', (_req, res) => {
  if (!_tdeVerdictJob) return res.json({ ok: false, error: 'no verdict computed yet — POST /api/trade-decision/macro-verdict/run' });
  if (_tdeVerdictJob.status === 'running') return res.json({ ok: true, status: 'running', elapsed: Math.round((Date.now() - _tdeVerdictJob.startedAt) / 1000) });
  if (_tdeVerdictJob.status === 'error') return res.status(500).json({ ok: false, status: 'error', error: _tdeVerdictJob.error });
  res.json({ ok: true, status: 'done', ..._tdeVerdictJob.result });
});

// Runtime config — the caps pattern: stored in KV (survives deploys, editable
// from the harness page without a restart); env vars are only the defaults for
// a blank KV. The scheduler below re-reads it each cycle, so changing the time
// or toggling the daily run takes effect live.
const TDE_CFG_KEY = 'trade_decision_cfg';
const TDE_CFG_DEFAULTS = {
  backfill_utc: process.env.TDE_BACKFILL_UTC || '03:05',
  backfill_daily: !['0', 'false', 'off'].includes(String(process.env.TDE_BACKFILL_DAILY ?? '').toLowerCase()),
  gap_fill: true,   // top the parquet history up from live OANDA M1 before replaying
};
let _tdeCfgCache = null, _tdeCfgCacheAt = 0;
async function tdeGetConfig(fresh = false) {
  if (!fresh && _tdeCfgCache && Date.now() - _tdeCfgCacheAt < 5 * 60_000) return _tdeCfgCache;
  let stored = {};
  try { const raw = await kv.get(TDE_CFG_KEY); if (raw) stored = typeof raw === 'string' ? JSON.parse(raw) : raw; }
  catch (e) { console.error('[tde] config read failed:', e.message ?? e); }
  _tdeCfgCache = { ...TDE_CFG_DEFAULTS, ...stored };
  _tdeCfgCacheAt = Date.now();
  return _tdeCfgCache;
}

app.get('/api/trade-decision/config', async (_req, res) => {
  res.json({ ok: true, config: await tdeGetConfig(true), defaults: TDE_CFG_DEFAULTS });
});

app.post('/api/trade-decision/config', express.json(), async (req, res) => {
  try {
    const cur = await tdeGetConfig(true);
    const next = { ...cur };
    if (typeof req.body?.backfill_utc === 'string' && /^\d{1,2}:\d{2}$/.test(req.body.backfill_utc)) next.backfill_utc = req.body.backfill_utc;
    if (typeof req.body?.backfill_daily === 'boolean') next.backfill_daily = req.body.backfill_daily;
    if (typeof req.body?.gap_fill === 'boolean') next.gap_fill = req.body.gap_fill;
    next.updatedAt = Date.now();
    await kv.put(TDE_CFG_KEY, JSON.stringify(next));
    _tdeCfgCache = next; _tdeCfgCacheAt = Date.now();
    res.json({ ok: true, config: next });
  } catch (e) { res.status(500).json({ ok: false, error: e.message ?? String(e) }); }
});

// Daily incremental top-up — ON by default at the configured UTC time (03:05
// unless changed in the config above). The stored parquet history is gap-filled
// from live OANDA M1 first (m1GapFill brick), so this does NOT depend on the R2
// store having been refreshed. Idempotent: no new sessions → nothing appended.
let tdeLastAutoBackfill = null;
setInterval(async () => {
  const cfg = await tdeGetConfig();
  if (!cfg.backfill_daily) return;
  const [bfH, bfM] = String(cfg.backfill_utc).split(':').map(x => parseInt(x, 10));
  const now = new Date();
  const today = now.toISOString().substring(0, 10);
  if (now.getUTCHours() === bfH && now.getUTCMinutes() === bfM
      && tdeLastAutoBackfill !== today && !tdeBackfillRunning) {
    tdeLastAutoBackfill = today;
    console.log(`[tde-backfill] daily incremental top-up starting (${cfg.backfill_utc} UTC, gap-fill ${cfg.gap_fill ? 'on' : 'off'})`);
    tdeStartBackfillJob(TDE_BACKFILL_PAIRS, { incremental: true, gapFill: cfg.gap_fill });
  }
}, 20_000);
console.log(`[tde-backfill] daily top-up armed (default ${TDE_CFG_DEFAULTS.backfill_utc} UTC — runtime-configurable at /api/trade-decision/config)`);

// ── Nightly research refresh ──────────────────────────────────────────────────
// Re-runs the vol-forecast research (all pairs) so the recalibration factors that
// feed the calibrated export stay current without any manual step. OFF unless
// VFR_REFRESH_UTC is set (HH:MM UTC, e.g. '02:30'). Fires an internal POST to the
// local route, reusing its exact logic (walk-forward eval, recalProposal, local +
// R2 persist). Heavy (~minutes) — meant for off-hours; the daily σ already updates
// itself, this only refreshes the slow structural correction factor.
const VFR_REFRESH_UTC = process.env.VFR_REFRESH_UTC || '';
let _vfrLastRefresh = '';
if (VFR_REFRESH_UTC && process.env.OANDA_KEY) {
  const [rH, rM] = VFR_REFRESH_UTC.split(':').map(x => parseInt(x, 10));
  setInterval(async () => {
    const now = new Date();
    const today = now.toISOString().slice(0, 10);
    if (now.getUTCHours() === rH && now.getUTCMinutes() === rM && _vfrLastRefresh !== today) {
      _vfrLastRefresh = today;
      try {
        await fetch(`http://127.0.0.1:${PORT}/api/vol-forecast-research/run`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
        console.log(`[vfr-refresh] nightly research kicked (${VFR_REFRESH_UTC} UTC)`);
      } catch (e) { console.warn(`[vfr-refresh] failed: ${e?.message}`); }
    }
  }, 20_000);
  console.log(`[vfr-refresh] nightly research refresh armed (${VFR_REFRESH_UTC} UTC)`);
}

// All other /api/* routes — call _worker.js and return the JSON response.
app.all('/api/*', async (req, res) => {
  try {
    const response = await callWorker(req);
    res.status(response.status);
    response.headers.forEach((val, key) => {
      const k = key.toLowerCase();
      // Drop hop-by-hop headers that Express handles itself
      if (k !== 'content-encoding' && k !== 'transfer-encoding') res.setHeader(key, val);
    });
    res.send(await response.text());
  } catch (e) {
    console.error('[API]', e.message);
    res.status(500).json({ error: e.message });
  }
});

// Dashboard static assets — served from project root.
// journal.html and backtest.html are served as-is; index.html is the fallback.
app.use(express.static(__dirname, {
  index:      'index.html',
  extensions: ['html'],
  setHeaders(res, filePath) {
    if (filePath.endsWith('.html')) res.setHeader('Cache-Control', 'no-cache');
  },
}));

// SPA fallback — catches clean URLs not matched by express.static
app.get('*', (_req, res) => res.sendFile(path.join(__dirname, 'index.html')));

// ── Boot ──────────────────────────────────────────────────────────────────────

// ── Level refresh loop ────────────────────────────────────────────────────────

async function runLevelsRefresh() {
  // Watchdog: if a previous refresh has been running for >5 min, force-release the lock
  if (state.levelsRefreshRunning && Date.now() - state.levelsRefreshStartedAt > 5 * 60_000) {
    console.warn('[LEVELS] Watchdog: releasing stuck refresh lock (hung >5 min)');
    state.levelsRefreshRunning = false;
  }
  if (state.levelsRefreshRunning || !process.env.OANDA_KEY) return;
  state.levelsRefreshRunning = true;
  state.levelsRefreshStartedAt = Date.now();
  try {
    const pairs = state.cfg?.pairs?.length ? state.cfg.pairs : DEFAULT_PAIRS;
    await refreshAllPairs(pairs);
    state.levelsRefreshAt = Date.now();
    await reloadLevels();

    // Telegram-v2: apply the frozen policy to the same pairs (no-ops if no policy
    // in KV yet). Server-side on Railway — the SAME interval as v1, NOT the
    // Cloudflare cron-worker. Isolated so a v2 error never breaks the v1 refresh.
    try { await refreshAllPairsV2(pairs); }
    catch (e) { console.error('[LEVELS-V2] refresh error:', e.message); }

    // Compute HMM regime for each pair using last 200 daily closes (1 year)
    const hmmResults = [];
    for (const sym of pairs) {
      const closes = await fetchDailyCandles(sym, 201);
      if (closes && closes.length >= 20) {
        const returns = [];
        for (let i = 1; i < closes.length; i++) {
          returns.push(Math.log(closes[i] / closes[i - 1]));
        }
        const result = fitHMM(returns);
        if (result) {
          // Preserve intraday30m set by reloadLevels() — don't clobber it
          state.hmmRegimes[sym] = { ...result, intraday30m: state.hmmRegimes[sym]?.intraday30m };
          const reliableTag = result.reliable ? '' : '⚠ambiguous';
          hmmResults.push(`${sym}:${result.regime}${result.trendDir ? `(${result.trendDir})` : ''}@${Math.round(result.rangeProb * 100)}%range ratio=${result.sigmaRatio?.toFixed(2)}${reliableTag}`);
        }
      }
    }
    if (hmmResults.length) console.log('[HMM]', hmmResults.join(' | '));

  } catch (e) {
    console.error('[LEVELS] Refresh error:', e.message);
  } finally {
    state.levelsRefreshRunning = false;
  }
}

async function runHMM5mRefresh() {
  if (!process.env.OANDA_KEY) return;
  const pairs   = state.cfg?.pairs?.length ? state.cfg.pairs : DEFAULT_PAIRS;
  const results = [];

  for (const sym of pairs) {
    try {
      const bars = await fetchHMMBars(sym, 500);
      if (!bars || bars.length < 150) continue;
      state.hmm5mBars[sym] = bars; // cache M1 bars for polarity flip detection

      const result = computeHMM5m(bars, sym);
      if (!result) continue;

      const prev = state.hmm5mRegimes[sym];
      state.hmm5mRegimes[sym] = result;

      // Telegram alert on regime change, with cooldown
      if (prev && prev.regime !== result.regime && state.cfg?.enabled !== false && state.cfg?.regimeChangeAlerts !== false) {
        const lastAlert = state.hmm5mLastAlert[sym] ?? 0;
        const now       = Date.now();
        if (now - lastAlert >= HMM5M_ALERT_COOLDOWN_MS && state.tg?.token && state.tg?.chatId) {
          const timeStr = new Date(result.computedAt)
            .toISOString().replace('T', ' ').substring(0, 16) + ' UTC';
          const msg = [
            `🔄 <b>${sym} Regime Change</b>`,
            `${prev.regime} → <b>${result.regime}</b>`,
            `Bull: <b>${result.pBull}%</b>  ·  Bear: ${result.pBear}%  ·  Range: ${result.pRange}%`,
            `Confidence: <b>${result.confidence}%</b>`,
            `<i>${timeStr}</i>`,
          ].join('\n');
          const sent = await sendTelegram(state.tg.token, state.tg.chatId, msg);
          if (sent) state.hmm5mLastAlert[sym] = now;
        }
      }

      results.push(`${sym}:${result.regime}@${result.confidence}%`);
    } catch (e) {
      console.error(`[HMM5M] ${sym} error:`, e.message);
    }
  }

  if (results.length) console.log('[HMM5M]', results.join(' | '));
}

